// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/IIdentityRegistry.sol";

/**
 * @title DynamicLeaseManager
 * @dev Advanced lease management with dynamic terms and flexible configurations
 * @notice Purpose: Handle complex lease scenarios with variable terms, escalations, and automated features
 * 
 * Dynamic Features:
 * - Variable rent schedules with automatic escalations
 * - Flexible payment frequencies (monthly, quarterly, annually)
 * - Dynamic security deposit calculations
 * - Rent-to-own conversions
 * - Automated lease renewals
 * - Performance-based rent adjustments
 * - Multi-party lease agreements
 */
contract DynamicLeaseManager is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;
    
    // Role definitions
    bytes32 public constant LEASE_MANAGER_ROLE = keccak256("LEASE_MANAGER_ROLE");
    bytes32 public constant PROPERTY_MANAGER_ROLE = keccak256("PROPERTY_MANAGER_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");
    
    // Identity registry for KYC verification
    IIdentityRegistry public immutable identityRegistry;
    
    // Lease status enumeration
    enum LeaseStatus {
        DRAFT,          // Lease created but not active
        ACTIVE,         // Lease is active and running
        PAUSED,         // Lease temporarily paused
        RENEWAL,        // In renewal process
        COMPLETED,      // Lease completed normally
        TERMINATED,     // Early termination
        DEFAULTED,      // Tenant in default
        CONVERTING      // Converting to ownership
    }
    
    // Payment frequency options
    enum PaymentFrequency {
        MONTHLY,
        QUARTERLY,
        SEMI_ANNUALLY,
        ANNUALLY,
        CUSTOM
    }
    
    // Rent adjustment types
    enum RentAdjustmentType {
        FIXED,              // Fixed rent amount
        PERCENTAGE,         // Percentage increase
        MARKET_RATE,        // Based on market data
        PERFORMANCE,        // Based on property performance
        CPI_INDEXED        // Consumer Price Index linked
    }
    
    // Dynamic lease terms
    struct LeaseTerms {
        PaymentFrequency paymentFrequency;      // How often rent is paid
        uint256 customPaymentDays;              // Days for custom frequency
        RentAdjustmentType adjustmentType;      // Type of rent adjustment
        uint256 adjustmentRate;                 // Rate for adjustments (basis points)
        uint256 adjustmentInterval;             // How often adjustments happen (seconds)
        bool autoRenewal;                       // Automatic lease renewal
        uint256 renewalTerms;                   // Length of renewal period
        bool rentToOwnOption;                   // Rent-to-own conversion available
        uint256 ownershipConversionRate;        // Conversion rate (basis points)
        uint256 maxRentIncrease;               // Max rent increase per adjustment (basis points)
        uint256 gracePeriod;                   // Grace period for late payments
        bool earlyTerminationAllowed;          // Early termination permitted
        uint256 earlyTerminationPenalty;       // Penalty for early termination
    }
    
    // Lease structure with dynamic features
    struct DynamicLease {
        uint256 leaseId;                    // Unique identifier
        address landlord;                   // Property owner
        address tenant;                     // Primary tenant
        address[] coTenants;                // Additional tenants
        IERC20 paymentToken;               // Payment token
        uint256 baseRent;                  // Base rent amount
        uint256 currentRent;               // Current rent (may differ from base due to adjustments)
        uint256 securityDeposit;           // Security deposit amount
        uint256 startDate;                 // Lease start
        uint256 endDate;                   // Lease end
        uint256 nextPaymentDue;            // Next payment due date
        uint256 nextAdjustmentDate;        // Next rent adjustment date
        LeaseStatus status;                // Current status
        LeaseTerms terms;                  // Dynamic terms
        string propertyMetadata;           // Property details/IPFS CID
        uint256 totalPaid;                 // Total amount paid
        uint256 paymentsMissed;            // Number of missed payments
        uint256 ownershipPercentage;       // Percentage owned (for rent-to-own)
        bool isRentToOwn;                  // Currently in rent-to-own mode
    }
    
    // Payment schedule entry
    struct PaymentSchedule {
        uint256 dueDate;
        uint256 amount;
        bool isPaid;
        uint256 paidDate;
        uint256 paidAmount;
    }
    
    // Storage
    mapping(uint256 => DynamicLease) public leases;
    mapping(uint256 => PaymentSchedule[]) public paymentSchedules;
    mapping(address => uint256[]) public landlordLeases;
    mapping(address => uint256[]) public tenantLeases;
    mapping(address => bool) public approvedTokens;
    mapping(uint256 => mapping(address => bool)) public authorizedManagers; // leaseId => manager => authorized
    
    // Market data for dynamic pricing (could be updated by oracles)
    mapping(string => uint256) public marketRates; // location => rate per sqft
    mapping(string => uint256) public cpiIndex;    // region => CPI value
    
    uint256 private _nextLeaseId = 1;
    
    // Events
    event DynamicLeaseCreated(
        uint256 indexed leaseId,
        address indexed landlord,
        address indexed tenant,
        uint256 baseRent,
        PaymentFrequency frequency
    );
    
    event RentAdjusted(
        uint256 indexed leaseId,
        uint256 oldRent,
        uint256 newRent,
        RentAdjustmentType adjustmentType
    );
    
    event PaymentScheduleGenerated(
        uint256 indexed leaseId,
        uint256 numberOfPayments
    );
    
    event RentToOwnActivated(
        uint256 indexed leaseId,
        uint256 ownershipPercentage
    );
    
    event LeaseRenewed(
        uint256 indexed leaseId,
        uint256 newEndDate,
        uint256 newRent
    );
    
    event CoTenantAdded(
        uint256 indexed leaseId,
        address indexed coTenant
    );
    
    event MarketRateUpdated(
        string indexed location,
        uint256 newRate
    );
    
    constructor(address _identityRegistry) {
        require(_identityRegistry != address(0), "DynamicLeaseManager: invalid identity registry");
        
        identityRegistry = IIdentityRegistry(_identityRegistry);
        
        // Setup roles
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(LEASE_MANAGER_ROLE, msg.sender);
        _grantRole(PROPERTY_MANAGER_ROLE, msg.sender);
        _grantRole(ORACLE_ROLE, msg.sender);
    }
    
    /**
     * @dev Create a dynamic lease with flexible terms
     * @param _tenant Primary tenant address
     * @param _paymentToken Payment token contract
     * @param _baseRent Base rent amount
     * @param _securityDeposit Security deposit
     * @param _startDate Lease start date
     * @param _endDate Lease end date
     * @param _terms Dynamic lease terms
     * @param _propertyMetadata Property metadata
     * @return uint256 Lease ID
     */
    function createDynamicLease(
        address _tenant,
        IERC20 _paymentToken,
        uint256 _baseRent,
        uint256 _securityDeposit,
        uint256 _startDate,
        uint256 _endDate,
        LeaseTerms memory _terms,
        string memory _propertyMetadata
    ) external nonReentrant onlyRole(LEASE_MANAGER_ROLE) returns (uint256) {
        require(_tenant != address(0), "DynamicLeaseManager: invalid tenant");
        require(_tenant != msg.sender, "DynamicLeaseManager: landlord cannot be tenant");
        require(approvedTokens[address(_paymentToken)], "DynamicLeaseManager: token not approved");
        require(_baseRent > 0, "DynamicLeaseManager: rent must be positive");
        require(_startDate >= block.timestamp, "DynamicLeaseManager: start date in past");
        require(_endDate > _startDate, "DynamicLeaseManager: invalid lease period");
        
        // Verify identity compliance
        require(identityRegistry.isVerified(msg.sender), "DynamicLeaseManager: landlord not verified");
        require(identityRegistry.isVerified(_tenant), "DynamicLeaseManager: tenant not verified");
        
        uint256 leaseId = _nextLeaseId++;
        
        // Calculate first payment due date based on frequency
        uint256 nextPayment = _calculateNextPaymentDate(_startDate, _terms.paymentFrequency, _terms.customPaymentDays);
        uint256 nextAdjustment = _terms.adjustmentInterval > 0 ? _startDate + _terms.adjustmentInterval : 0;
        
        // Create lease
        DynamicLease storage lease = leases[leaseId];
        lease.leaseId = leaseId;
        lease.landlord = msg.sender;
        lease.tenant = _tenant;
        lease.paymentToken = _paymentToken;
        lease.baseRent = _baseRent;
        lease.currentRent = _baseRent;
        lease.securityDeposit = _securityDeposit;
        lease.startDate = _startDate;
        lease.endDate = _endDate;
        lease.nextPaymentDue = nextPayment;
        lease.nextAdjustmentDate = nextAdjustment;
        lease.status = LeaseStatus.DRAFT;
        lease.terms = _terms;
        lease.propertyMetadata = _propertyMetadata;
        lease.totalPaid = 0;
        lease.paymentsMissed = 0;
        lease.ownershipPercentage = 0;
        lease.isRentToOwn = false;
        
        // Track leases
        landlordLeases[msg.sender].push(leaseId);
        tenantLeases[_tenant].push(leaseId);
        
        // Generate initial payment schedule
        _generatePaymentSchedule(leaseId);
        
        emit DynamicLeaseCreated(leaseId, msg.sender, _tenant, _baseRent, _terms.paymentFrequency);
        
        return leaseId;
    }
    
    /**
     * @dev Activate lease after security deposit is paid
     * @param leaseId The lease ID
     */
    function activateLease(uint256 leaseId) external nonReentrant {
        DynamicLease storage lease = leases[leaseId];
        require(lease.landlord != address(0), "DynamicLeaseManager: lease not found");
        require(msg.sender == lease.tenant, "DynamicLeaseManager: only tenant can activate");
        require(lease.status == LeaseStatus.DRAFT, "DynamicLeaseManager: invalid status");
        
        // Transfer security deposit
        lease.paymentToken.safeTransferFrom(msg.sender, address(this), lease.securityDeposit);
        
        lease.status = LeaseStatus.ACTIVE;
        emit LeaseStatusChanged(leaseId, LeaseStatus.DRAFT, LeaseStatus.ACTIVE);
    }
    
    /**
     * @dev Pay rent with automatic rent-to-own conversion tracking
     * @param leaseId The lease ID
     */
    function payRent(uint256 leaseId) external nonReentrant {
        DynamicLease storage lease = leases[leaseId];
        require(lease.landlord != address(0), "DynamicLeaseManager: lease not found");
        require(msg.sender == lease.tenant || _isCoTenant(leaseId, msg.sender), "DynamicLeaseManager: unauthorized");
        require(lease.status == LeaseStatus.ACTIVE, "DynamicLeaseManager: lease not active");
        
        uint256 rentAmount = lease.currentRent;
        
        // Transfer rent to landlord
        lease.paymentToken.safeTransferFrom(msg.sender, lease.landlord, rentAmount);
        
        // Update lease state
        lease.totalPaid += rentAmount;
        lease.nextPaymentDue = _calculateNextPaymentDate(
            lease.nextPaymentDue, 
            lease.terms.paymentFrequency, 
            lease.terms.customPaymentDays
        );
        
        // Handle rent-to-own conversion
        if (lease.terms.rentToOwnOption && lease.isRentToOwn) {
            uint256 ownershipIncrease = (rentAmount * lease.terms.ownershipConversionRate) / 10000;
            lease.ownershipPercentage += ownershipIncrease;
            
            // Check if full ownership achieved
            if (lease.ownershipPercentage >= 10000) { // 100% in basis points
                lease.status = LeaseStatus.CONVERTING;
                emit RentToOwnActivated(leaseId, lease.ownershipPercentage);
            }
        }
        
        emit RentPaid(leaseId, msg.sender, rentAmount, block.timestamp);
    }
    
    /**
     * @dev Adjust rent based on dynamic terms
     * @param leaseId The lease ID
     */
    function adjustRent(uint256 leaseId) external {
        DynamicLease storage lease = leases[leaseId];
        require(lease.landlord != address(0), "DynamicLeaseManager: lease not found");
        require(lease.status == LeaseStatus.ACTIVE, "DynamicLeaseManager: lease not active");
        require(block.timestamp >= lease.nextAdjustmentDate, "DynamicLeaseManager: adjustment not due");
        
        uint256 oldRent = lease.currentRent;
        uint256 newRent = _calculateRentAdjustment(leaseId);
        
        // Ensure adjustment doesn't exceed maximum
        uint256 maxIncrease = (oldRent * lease.terms.maxRentIncrease) / 10000;
        if (newRent > oldRent + maxIncrease) {
            newRent = oldRent + maxIncrease;
        }
        
        lease.currentRent = newRent;
        lease.nextAdjustmentDate = block.timestamp + lease.terms.adjustmentInterval;
        
        // Regenerate payment schedule with new rent
        _generatePaymentSchedule(leaseId);
        
        emit RentAdjusted(leaseId, oldRent, newRent, lease.terms.adjustmentType);
    }
    
    /**
     * @dev Activate rent-to-own option
     * @param leaseId The lease ID
     */
    function activateRentToOwn(uint256 leaseId) external {
        DynamicLease storage lease = leases[leaseId];
        require(lease.landlord != address(0), "DynamicLeaseManager: lease not found");
        require(msg.sender == lease.tenant, "DynamicLeaseManager: only tenant can activate");
        require(lease.terms.rentToOwnOption, "DynamicLeaseManager: rent-to-own not available");
        require(!lease.isRentToOwn, "DynamicLeaseManager: already activated");
        
        lease.isRentToOwn = true;
        emit RentToOwnActivated(leaseId, 0);
    }
    
    /**
     * @dev Add co-tenant to lease
     * @param leaseId The lease ID
     * @param coTenant Co-tenant address
     */
    function addCoTenant(uint256 leaseId, address coTenant) external {
        DynamicLease storage lease = leases[leaseId];
        require(lease.landlord != address(0), "DynamicLeaseManager: lease not found");
        require(msg.sender == lease.landlord, "DynamicLeaseManager: only landlord can add");
        require(identityRegistry.isVerified(coTenant), "DynamicLeaseManager: co-tenant not verified");
        
        lease.coTenants.push(coTenant);
        tenantLeases[coTenant].push(leaseId);
        
        emit CoTenantAdded(leaseId, coTenant);
    }
    
    /**
     * @dev Update market rates (Oracle function)
     * @param location Location identifier
     * @param newRate New market rate
     */
    function updateMarketRate(string memory location, uint256 newRate) external onlyRole(ORACLE_ROLE) {
        marketRates[location] = newRate;
        emit MarketRateUpdated(location, newRate);
    }
    
    /**
     * @dev Auto-renew lease if enabled
     * @param leaseId The lease ID
     */
    function autoRenewLease(uint256 leaseId) external {
        DynamicLease storage lease = leases[leaseId];
        require(lease.landlord != address(0), "DynamicLeaseManager: lease not found");
        require(lease.terms.autoRenewal, "DynamicLeaseManager: auto-renewal not enabled");
        require(block.timestamp >= lease.endDate, "DynamicLeaseManager: lease not expired");
        require(lease.status == LeaseStatus.ACTIVE, "DynamicLeaseManager: lease not active");
        
        // Renew lease
        lease.endDate = lease.endDate + lease.terms.renewalTerms;
        lease.status = LeaseStatus.RENEWAL;
        
        // Regenerate payment schedule for renewal period
        _generatePaymentSchedule(leaseId);
        
        emit LeaseRenewed(leaseId, lease.endDate, lease.currentRent);
    }
    
    // Internal functions
    function _calculateNextPaymentDate(uint256 currentDate, PaymentFrequency frequency, uint256 customDays) internal pure returns (uint256) {
        if (frequency == PaymentFrequency.MONTHLY) {
            return currentDate + 30 days;
        } else if (frequency == PaymentFrequency.QUARTERLY) {
            return currentDate + 90 days;
        } else if (frequency == PaymentFrequency.SEMI_ANNUALLY) {
            return currentDate + 180 days;
        } else if (frequency == PaymentFrequency.ANNUALLY) {
            return currentDate + 365 days;
        } else {
            return currentDate + (customDays * 1 days);
        }
    }
    
    function _calculateRentAdjustment(uint256 leaseId) internal view returns (uint256) {
        DynamicLease memory lease = leases[leaseId];
        
        if (lease.terms.adjustmentType == RentAdjustmentType.FIXED) {
            return lease.currentRent; // No change
        } else if (lease.terms.adjustmentType == RentAdjustmentType.PERCENTAGE) {
            return lease.currentRent + (lease.currentRent * lease.terms.adjustmentRate) / 10000;
        } else if (lease.terms.adjustmentType == RentAdjustmentType.MARKET_RATE) {
            // Simplified market rate adjustment
            return lease.currentRent + (lease.currentRent * lease.terms.adjustmentRate) / 10000;
        } else if (lease.terms.adjustmentType == RentAdjustmentType.PERFORMANCE) {
            // Performance-based adjustment (simplified)
            return lease.currentRent + (lease.currentRent * lease.terms.adjustmentRate) / 10000;
        } else {
            // CPI_INDEXED or default
            return lease.currentRent + (lease.currentRent * lease.terms.adjustmentRate) / 10000;
        }
    }
    
    function _generatePaymentSchedule(uint256 leaseId) internal {
        DynamicLease memory lease = leases[leaseId];
        
        // Clear existing schedule
        delete paymentSchedules[leaseId];
        
        uint256 currentDate = lease.nextPaymentDue;
        uint256 paymentCount = 0;
        
        while (currentDate <= lease.endDate && paymentCount < 120) { // Max 120 payments (10 years monthly)
            PaymentSchedule memory payment = PaymentSchedule({
                dueDate: currentDate,
                amount: lease.currentRent,
                isPaid: false,
                paidDate: 0,
                paidAmount: 0
            });
            
            paymentSchedules[leaseId].push(payment);
            
            currentDate = _calculateNextPaymentDate(currentDate, lease.terms.paymentFrequency, lease.terms.customPaymentDays);
            paymentCount++;
        }
        
        emit PaymentScheduleGenerated(leaseId, paymentCount);
    }
    
    function _isCoTenant(uint256 leaseId, address user) internal view returns (bool) {
        DynamicLease memory lease = leases[leaseId];
        for (uint256 i = 0; i < lease.coTenants.length; i++) {
            if (lease.coTenants[i] == user) {
                return true;
            }
        }
        return false;
    }
    
    // View functions
    function getDynamicLease(uint256 leaseId) external view returns (DynamicLease memory) {
        return leases[leaseId];
    }
    
    function getPaymentSchedule(uint256 leaseId) external view returns (PaymentSchedule[] memory) {
        return paymentSchedules[leaseId];
    }
    
    function isPaymentDue(uint256 leaseId) external view returns (bool) {
        DynamicLease memory lease = leases[leaseId];
        return block.timestamp >= lease.nextPaymentDue && lease.status == LeaseStatus.ACTIVE;
    }
    
    // Events (additional)
    event LeaseStatusChanged(uint256 indexed leaseId, LeaseStatus oldStatus, LeaseStatus newStatus);
    event RentPaid(uint256 indexed leaseId, address indexed payer, uint256 amount, uint256 timestamp);
    
    // Admin functions
    function addApprovedToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        approvedTokens[token] = true;
    }
    
    function removeApprovedToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        approvedTokens[token] = false;
    }
}

contracts/EscrowPayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./interfaces/IIdentityRegistry.sol";

/**
 * @title EscrowPayment
 * @dev Manages security deposits, rent payments, and escrow functionality
 * Integrates with Integra's fiat payment rails and on-chain proof-of-payment
 */
contract EscrowPayment is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    
    // Roles
    bytes32 public constant ESCROW_AGENT_ROLE = keccak256("ESCROW_AGENT_ROLE");
    bytes32 public constant PAYMENT_PROCESSOR_ROLE = keccak256("PAYMENT_PROCESSOR_ROLE");
    bytes32 public constant DISPUTE_RESOLVER_ROLE = keccak256("DISPUTE_RESOLVER_ROLE");
    
    // Escrow status enumeration
    enum EscrowStatus {
        CREATED,        // Escrow created, awaiting deposit
        FUNDED,         // Funds deposited in escrow
        RELEASED,       // Funds released to recipient
        REFUNDED,       // Funds refunded to depositor
        DISPUTED,       // Escrow under dispute
        EXPIRED         // Escrow expired
    }
    
    // Payment method enumeration
    enum PaymentMethod {
        CRYPTO,         // Direct crypto payment
        FIAT_BRIDGE,    // Fiat payment via Integra bridge
        HYBRID          // Combination of crypto and fiat
    }
    
    // Escrow structure for security deposits
    struct SecurityDepositEscrow {
        uint256 escrowId;
        uint256 leaseId;            // Associated lease agreement
        address landlord;           // Funds recipient
        address tenant;             // Funds depositor
        address paymentToken;       // ERC-20 token (USDC, IRL, etc.)
        uint256 amount;             // Deposit amount
        uint256 createdAt;          // Creation timestamp
        uint256 releaseDate;        // Earliest release date
        EscrowStatus status;        // Current status
        string releaseConditions;   // IPFS hash of release conditions
        bytes32 conditionsHash;     // Hash of conditions for verification
    }
    
    // Rent payment structure
    struct RentPayment {
        uint256 paymentId;
        uint256 leaseId;            // Associated lease
        address landlord;           // Payment recipient
        address tenant;             // Payment sender
        address paymentToken;       // Payment token
        uint256 amount;             // Payment amount
        uint256 dueDate;            // Payment due date
        uint256 paidDate;           // Actual payment date
        PaymentMethod method;       // Payment method used
        string fiatReference;       // Fiat payment reference (if applicable)
        bytes32 proofHash;          // Hash of payment proof
        bool isAutomated;           // Whether payment was automated
    }
    
    // Automated payment subscription
    struct PaymentSubscription {
        uint256 subscriptionId;
        uint256 leaseId;
        address tenant;
        address landlord;
        address paymentToken;
        uint256 amount;             // Monthly payment amount
        uint256 startDate;          // Subscription start
        uint256 endDate;            // Subscription end
        uint256 lastPayment;        // Last successful payment
        uint256 nextPayment;        // Next scheduled payment
        bool isActive;              // Subscription status
        uint256 failedPayments;     // Failed payment counter
    }
    
    // Storage mappings
    mapping(uint256 => SecurityDepositEscrow) public securityDeposits;
    mapping(uint256 => RentPayment) public rentPayments;
    mapping(uint256 => PaymentSubscription) public paymentSubscriptions;
    mapping(uint256 => uint256) public leaseToEscrow;           // leaseId => escrowId
    mapping(uint256 => uint256) public leaseToSubscription;     // leaseId => subscriptionId
    mapping(address => bool) public approvedTokens;
    mapping(address => uint256[]) public landlordEscrows;
    mapping(address => uint256[]) public tenantEscrows;
    
    // Counters
    uint256 private _escrowCounter;
    uint256 private _paymentCounter;
    uint256 private _subscriptionCounter;
    
    // Contract references
    IIdentityRegistry public identityRegistry;
    address public leaseAgreementContract;
    address public fiatBridge;                  // Integra fiat bridge contract
    
    // Configuration
    uint256 public defaultEscrowPeriod = 365 days;
    uint256 public maxEscrowPeriod = 5 * 365 days;
    uint256 public automatedPaymentGracePeriod = 3 days;
    uint256 public maxFailedPayments = 3;
    
    // Events
    event SecurityDepositCreated(
        uint256 indexed escrowId,
        uint256 indexed leaseId,
        address indexed tenant,
        address landlord,
        uint256 amount
    );
    
    event SecurityDepositFunded(
        uint256 indexed escrowId,
        address indexed tenant,
        uint256 amount
    );
    
    event SecurityDepositReleased(
        uint256 indexed escrowId,
        address indexed recipient,
        uint256 amount,
        string reason
    );
    
    event RentPaymentProcessed(
        uint256 indexed paymentId,
        uint256 indexed leaseId,
        address indexed tenant,
        address landlord,
        uint256 amount,
        PaymentMethod method
    );
    
    event PaymentSubscriptionCreated(
        uint256 indexed subscriptionId,
        uint256 indexed leaseId,
        address indexed tenant,
        uint256 amount
    );
    
    event AutomatedPaymentExecuted(
        uint256 indexed subscriptionId,
        uint256 indexed paymentId,
        uint256 amount
    );
    
    event AutomatedPaymentFailed(
        uint256 indexed subscriptionId,
        uint256 failureCount,
        string reason
    );
    
    event DisputeRaised(
        uint256 indexed escrowId,
        address indexed raisedBy,
        string reason
    );
    
    constructor(
        address _identityRegistry,
        address _leaseAgreementContract
    ) {
        require(_identityRegistry != address(0), "EscrowPayment: invalid identity registry");
        require(_leaseAgreementContract != address(0), "EscrowPayment: invalid lease contract");
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ESCROW_AGENT_ROLE, msg.sender);
        _grantRole(PAYMENT_PROCESSOR_ROLE, msg.sender);
        _grantRole(DISPUTE_RESOLVER_ROLE, msg.sender);
        
        identityRegistry = IIdentityRegistry(_identityRegistry);
        leaseAgreementContract = _leaseAgreementContract;
    }
    
    // Modifiers
    modifier onlyEscrowAgent() {
        require(hasRole(ESCROW_AGENT_ROLE, msg.sender), "EscrowPayment: not an escrow agent");
        _;
    }
    
    modifier onlyPaymentProcessor() {
        require(hasRole(PAYMENT_PROCESSOR_ROLE, msg.sender), "EscrowPayment: not payment processor");
        _;
    }
    
    modifier onlyDisputeResolver() {
        require(hasRole(DISPUTE_RESOLVER_ROLE, msg.sender), "EscrowPayment: not dispute resolver");
        _;
    }
    
    modifier validEscrow(uint256 _escrowId) {
        require(_escrowId > 0 && _escrowId <= _escrowCounter, "EscrowPayment: invalid escrow ID");
        require(securityDeposits[_escrowId].landlord != address(0), "EscrowPayment: escrow not found");
        _;
    }
    
    modifier onlyEscrowParties(uint256 _escrowId) {
        require(
            msg.sender == securityDeposits[_escrowId].landlord || 
            msg.sender == securityDeposits[_escrowId].tenant,
            "EscrowPayment: not an escrow party"
        );
        _;
    }
    
    modifier verifiedUsers(address _landlord, address _tenant) {
        require(identityRegistry.isVerified(_landlord), "EscrowPayment: landlord not verified");
        require(identityRegistry.isVerified(_tenant), "EscrowPayment: tenant not verified");
        _;
    }
    
    // Security Deposit Functions
    
    /**
     * @dev Create security deposit escrow for a lease
     */
    function createSecurityDepositEscrow(
        uint256 _leaseId,
        address _landlord,
        address _tenant,
        address _paymentToken,
        uint256 _amount,
        uint256 _releaseDate,
        string calldata _releaseConditions,
        bytes32 _conditionsHash
    ) external 
        whenNotPaused 
        verifiedUsers(_landlord, _tenant) 
        returns (uint256) 
    {
        require(_leaseId > 0, "EscrowPayment: invalid lease ID");
        require(_amount > 0, "EscrowPayment: invalid amount");
        require(approvedTokens[_paymentToken], "EscrowPayment: token not approved");
        require(_releaseDate > block.timestamp, "EscrowPayment: invalid release date");
        require(_releaseDate <= block.timestamp + maxEscrowPeriod, "EscrowPayment: release date too far");
        require(leaseToEscrow[_leaseId] == 0, "EscrowPayment: escrow already exists for lease");
        
        _escrowCounter++;
        uint256 escrowId = _escrowCounter;
        
        securityDeposits[escrowId] = SecurityDepositEscrow({
            escrowId: escrowId,
            leaseId: _leaseId,
            landlord: _landlord,
            tenant: _tenant,
            paymentToken: _paymentToken,
            amount: _amount,
            createdAt: block.timestamp,
            releaseDate: _releaseDate,
            status: EscrowStatus.CREATED,
            releaseConditions: _releaseConditions,
            conditionsHash: _conditionsHash
        });
        
        leaseToEscrow[_leaseId] = escrowId;
        landlordEscrows[_landlord].push(escrowId);
        tenantEscrows[_tenant].push(escrowId);
        
        emit SecurityDepositCreated(escrowId, _leaseId, _tenant, _landlord, _amount);
        
        return escrowId;
    }
    
    /**
     * @dev Fund security deposit escrow
     */
    function fundSecurityDeposit(uint256 _escrowId) 
        external 
        validEscrow(_escrowId) 
        nonReentrant 
    {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(msg.sender == escrow.tenant, "EscrowPayment: only tenant can fund");
        require(escrow.status == EscrowStatus.CREATED, "EscrowPayment: escrow not in created status");
        
        IERC20 token = IERC20(escrow.paymentToken);
        require(token.balanceOf(msg.sender) >= escrow.amount, "EscrowPayment: insufficient balance");
        
        token.safeTransferFrom(msg.sender, address(this), escrow.amount);
        
        escrow.status = EscrowStatus.FUNDED;
        
        emit SecurityDepositFunded(_escrowId, msg.sender, escrow.amount);
    }
    
    /**
     * @dev Release security deposit
     */
    function releaseSecurityDeposit(
        uint256 _escrowId, 
        address _recipient,
        uint256 _amount,
        string calldata _reason
    ) external validEscrow(_escrowId) onlyEscrowAgent nonReentrant {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(escrow.status == EscrowStatus.FUNDED, "EscrowPayment: escrow not funded");
        require(block.timestamp >= escrow.releaseDate, "EscrowPayment: release date not reached");
        require(_amount <= escrow.amount, "EscrowPayment: amount exceeds deposit");
        require(
            _recipient == escrow.landlord || _recipient == escrow.tenant,
            "EscrowPayment: invalid recipient"
        );
        
        IERC20 token = IERC20(escrow.paymentToken);
        token.safeTransfer(_recipient, _amount);
        
        if (_amount == escrow.amount) {
            escrow.status = EscrowStatus.RELEASED;
        } else {
            // Partial release - reduce escrow amount
            escrow.amount -= _amount;
        }
        
        emit SecurityDepositReleased(_escrowId, _recipient, _amount, _reason);
    }
    
    /**
     * @dev Refund security deposit to tenant
     */
    function refundSecurityDeposit(uint256 _escrowId, string calldata _reason) 
        external 
        validEscrow(_escrowId) 
        onlyEscrowAgent 
        nonReentrant 
    {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(escrow.status == EscrowStatus.FUNDED, "EscrowPayment: escrow not funded");
        
        IERC20 token = IERC20(escrow.paymentToken);
        token.safeTransfer(escrow.tenant, escrow.amount);
        
        escrow.status = EscrowStatus.REFUNDED;
        
        emit SecurityDepositReleased(_escrowId, escrow.tenant, escrow.amount, _reason);
    }
    
    // Rent Payment Functions
    
    /**
     * @dev Process rent payment
     */
    function processRentPayment(
        uint256 _leaseId,
        address _landlord,
        address _tenant,
        address _paymentToken,
        uint256 _amount,
        uint256 _dueDate,
        PaymentMethod _method,
        string calldata _fiatReference,
        bytes32 _proofHash
    ) external 
        whenNotPaused 
        onlyPaymentProcessor 
        nonReentrant 
        returns (uint256) 
    {
        require(_amount > 0, "EscrowPayment: invalid amount");
        require(approvedTokens[_paymentToken], "EscrowPayment: token not approved");
        require(identityRegistry.isVerified(_landlord), "EscrowPayment: landlord not verified");
        require(identityRegistry.isVerified(_tenant), "EscrowPayment: tenant not verified");
        
        _paymentCounter++;
        uint256 paymentId = _paymentCounter;
        
        if (_method == PaymentMethod.CRYPTO) {
            IERC20 token = IERC20(_paymentToken);
            token.safeTransferFrom(_tenant, _landlord, _amount);
        }
        // For FIAT_BRIDGE and HYBRID, funds are handled by external bridge
        
        rentPayments[paymentId] = RentPayment({
            paymentId: paymentId,
            leaseId: _leaseId,
            landlord: _landlord,
            tenant: _tenant,
            paymentToken: _paymentToken,
            amount: _amount,
            dueDate: _dueDate,
            paidDate: block.timestamp,
            method: _method,
            fiatReference: _fiatReference,
            proofHash: _proofHash,
            isAutomated: false
        });
        
        emit RentPaymentProcessed(paymentId, _leaseId, _tenant, _landlord, _amount, _method);
        
        return paymentId;
    }
    
    // Automated Payment Functions
    
    /**
     * @dev Create automated payment subscription for rent
     */
    function createPaymentSubscription(
        uint256 _leaseId,
        address _tenant,
        address _landlord,
        address _paymentToken,
        uint256 _monthlyAmount,
        uint256 _startDate,
        uint256 _endDate
    ) external 
        whenNotPaused 
        verifiedUsers(_landlord, _tenant) 
        returns (uint256) 
    {
        require(_leaseId > 0, "EscrowPayment: invalid lease ID");
        require(_monthlyAmount > 0, "EscrowPayment: invalid amount");
        require(approvedTokens[_paymentToken], "EscrowPayment: token not approved");
        require(_startDate >= block.timestamp, "EscrowPayment: start date in past");
        require(_endDate > _startDate, "EscrowPayment: invalid subscription period");
        require(leaseToSubscription[_leaseId] == 0, "EscrowPayment: subscription already exists");
        
        _subscriptionCounter++;
        uint256 subscriptionId = _subscriptionCounter;
        
        paymentSubscriptions[subscriptionId] = PaymentSubscription({
            subscriptionId: subscriptionId,
            leaseId: _leaseId,
            tenant: _tenant,
            landlord: _landlord,
            paymentToken: _paymentToken,
            amount: _monthlyAmount,
            startDate: _startDate,
            endDate: _endDate,
            lastPayment: 0,
            nextPayment: _startDate,
            isActive: true,
            failedPayments: 0
        });
        
        leaseToSubscription[_leaseId] = subscriptionId;
        
        emit PaymentSubscriptionCreated(subscriptionId, _leaseId, _tenant, _monthlyAmount);
        
        return subscriptionId;
    }
    
    /**
     * @dev Execute automated payment
     */
    function executeAutomatedPayment(uint256 _subscriptionId) 
        public 
        onlyPaymentProcessor 
        nonReentrant 
        returns (uint256) 
    {
        PaymentSubscription storage subscription = paymentSubscriptions[_subscriptionId];
        require(subscription.isActive, "EscrowPayment: subscription not active");
        require(block.timestamp >= subscription.nextPayment, "EscrowPayment: payment not due");
        require(block.timestamp <= subscription.endDate, "EscrowPayment: subscription expired");
        
        IERC20 token = IERC20(subscription.paymentToken);
        
        try token.transferFrom(subscription.tenant, subscription.landlord, subscription.amount) {
            _paymentCounter++;
            uint256 paymentId = _paymentCounter;
            
            rentPayments[paymentId] = RentPayment({
                paymentId: paymentId,
                leaseId: subscription.leaseId,
                landlord: subscription.landlord,
                tenant: subscription.tenant,
                paymentToken: subscription.paymentToken,
                amount: subscription.amount,
                dueDate: subscription.nextPayment,
                paidDate: block.timestamp,
                method: PaymentMethod.CRYPTO,
                fiatReference: "",
                proofHash: bytes32(0),
                isAutomated: true
            });
            
            subscription.lastPayment = block.timestamp;
            subscription.nextPayment += 30 days; // Move to next month
            subscription.failedPayments = 0; // Reset failure counter
            
            emit AutomatedPaymentExecuted(_subscriptionId, paymentId, subscription.amount);
            emit RentPaymentProcessed(
                paymentId, 
                subscription.leaseId, 
                subscription.tenant, 
                subscription.landlord, 
                subscription.amount, 
                PaymentMethod.CRYPTO
            );
            
            return paymentId;
        } catch {
            subscription.failedPayments++;
            
            if (subscription.failedPayments >= maxFailedPayments) {
                subscription.isActive = false;
            }
            
            emit AutomatedPaymentFailed(_subscriptionId, subscription.failedPayments, "Transfer failed");
            
            return 0;
        }
    }
    
    /**
     * @dev Cancel payment subscription
     */
    function cancelPaymentSubscription(uint256 _subscriptionId) 
        external 
    {
        PaymentSubscription storage subscription = paymentSubscriptions[_subscriptionId];
        require(
            msg.sender == subscription.tenant || 
            msg.sender == subscription.landlord ||
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "EscrowPayment: not authorized to cancel"
        );
        
        subscription.isActive = false;
    }
    
    // Dispute Functions
    
    /**
     * @dev Raise dispute on escrow
     */
    function raiseEscrowDispute(uint256 _escrowId, string calldata _reason) 
        external 
        validEscrow(_escrowId) 
        onlyEscrowParties(_escrowId) 
    {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(escrow.status == EscrowStatus.FUNDED, "EscrowPayment: escrow not funded");
        
        escrow.status = EscrowStatus.DISPUTED;
        
        emit DisputeRaised(_escrowId, msg.sender, _reason);
    }
    
    /**
     * @dev Resolve escrow dispute
     */
    function resolveEscrowDispute(
        uint256 _escrowId, 
        address _recipient,
        uint256 _amount,
        string calldata _resolution
    ) external validEscrow(_escrowId) onlyDisputeResolver nonReentrant {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(escrow.status == EscrowStatus.DISPUTED, "EscrowPayment: not disputed");
        require(_amount <= escrow.amount, "EscrowPayment: amount exceeds deposit");
        require(
            _recipient == escrow.landlord || _recipient == escrow.tenant,
            "EscrowPayment: invalid recipient"
        );
        
        IERC20 token = IERC20(escrow.paymentToken);
        token.safeTransfer(_recipient, _amount);
        
        if (_amount == escrow.amount) {
            escrow.status = EscrowStatus.RELEASED;
        } else {
            escrow.amount -= _amount;
            escrow.status = EscrowStatus.FUNDED; // Return to funded status for remainder
        }
        
        emit SecurityDepositReleased(_escrowId, _recipient, _amount, _resolution);
    }
    
    // View Functions
    
    /**
     * @dev Get security deposit details
     */
    function getSecurityDeposit(uint256 _escrowId) 
        external 
        view 
        validEscrow(_escrowId) 
        returns (SecurityDepositEscrow memory) 
    {
        return securityDeposits[_escrowId];
    }
    
    /**
     * @dev Get rent payment details
     */
    function getRentPayment(uint256 _paymentId) 
        external 
        view 
        returns (RentPayment memory) 
    {
        require(_paymentId > 0 && _paymentId <= _paymentCounter, "EscrowPayment: invalid payment ID");
        return rentPayments[_paymentId];
    }
    
    /**
     * @dev Get payment subscription details
     */
    function getPaymentSubscription(uint256 _subscriptionId) 
        external 
        view 
        returns (PaymentSubscription memory) 
    {
        require(_subscriptionId > 0 && _subscriptionId <= _subscriptionCounter, 
                "EscrowPayment: invalid subscription ID");
        return paymentSubscriptions[_subscriptionId];
    }
    
    /**
     * @dev Get landlord's escrows
     */
    function getLandlordEscrows(address _landlord) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return landlordEscrows[_landlord];
    }
    
    /**
     * @dev Get tenant's escrows
     */
    function getTenantEscrows(address _tenant) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return tenantEscrows[_tenant];
    }
    
    /**
     * @dev Get escrow ID for lease
     */
    function getLeaseEscrow(uint256 _leaseId) 
        external 
        view 
        returns (uint256) 
    {
        return leaseToEscrow[_leaseId];
    }
    
    /**
     * @dev Get subscription ID for lease
     */
    function getLeaseSubscription(uint256 _leaseId) 
        external 
        view 
        returns (uint256) 
    {
        return leaseToSubscription[_leaseId];
    }
    
    // Administrative Functions
    
    /**
     * @dev Set approved payment token
     */
    function setApprovedToken(address _token, bool _approved) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        approvedTokens[_token] = _approved;
    }
    
    /**
     * @dev Set fiat bridge contract
     */
    function setFiatBridge(address _fiatBridge) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        fiatBridge = _fiatBridge;
    }
    
    /**
     * @dev Update configuration parameters
     */
    function updateConfiguration(
        uint256 _defaultEscrowPeriod,
        uint256 _maxEscrowPeriod,
        uint256 _gracePeriod,
        uint256 _maxFailedPayments
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        defaultEscrowPeriod = _defaultEscrowPeriod;
        maxEscrowPeriod = _maxEscrowPeriod;
        automatedPaymentGracePeriod = _gracePeriod;
        maxFailedPayments = _maxFailedPayments;
    }
    
    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }
    
    /**
     * @dev Unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }
    
    /**
     * @dev Batch execute automated payments
     */
    function batchExecuteAutomatedPayments(uint256[] calldata _subscriptionIds) 
        external 
        onlyPaymentProcessor 
    {
        for (uint256 i = 0; i < _subscriptionIds.length; i++) {
            if (_subscriptionIds[i] > 0 && _subscriptionIds[i] <= _subscriptionCounter) {
                PaymentSubscription memory subscription = paymentSubscriptions[_subscriptionIds[i]];
                if (subscription.isActive && 
                    block.timestamp >= subscription.nextPayment &&
                    block.timestamp <= subscription.endDate) {
                    this.executeAutomatedPayment(_subscriptionIds[i]);
                }
            }
        }
    }
}

contracts/IdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

contract IdentityRegistry is Ownable {

    struct Identity {
        address onchainId;
        uint16 country;
        bool isVerified;
        uint256 timestamp;
    }

    mapping(address => Identity) private _identities;
    mapping(address => bool) private _registered;

    event IdentityRegistered(address indexed user, address indexed onchainId, uint16 country);
    event IdentityVerified(address indexed user, address indexed verifier);

    constructor() Ownable(msg.sender) {}

    function registerIdentity(address _onchainId) external {
        require(!_registered[msg.sender], "Already registered");
        require(_onchainId != address(0), "Invalid identity");

        _identities[msg.sender] = Identity({
            onchainId: _onchainId,
            country: 0,
            isVerified: false,
            timestamp: block.timestamp
        });

        _registered[msg.sender] = true;
        emit IdentityRegistered(msg.sender, _onchainId, 0);
    }

    function adminVerify(address _user, address _onchainId, uint16 _country) external onlyOwner {
        require(_registered[_user], "User not registered");
        require(_country > 0, "Invalid country");

        _identities[_user].onchainId = _onchainId;
        _identities[_user].country = _country;
        _identities[_user].isVerified = true;

        emit IdentityVerified(_user, msg.sender);
    }

    function isVerified(address _user) external view returns (bool) {
        return _identities[_user].isVerified;
    }

    function investorCountry(address _user) external view returns (uint16) {
        return _identities[_user].country;
    }

    function getCountry(address _user) external view returns (uint16) {
        return _identities[_user].country;
    }

    function getIdentityDetails(address _user) external view returns (address, uint16, bool, uint256) {
        Identity memory identity = _identities[_user];
        return (identity.onchainId, identity.country, identity.isVerified, identity.timestamp);
    }

    function isRegistered(address _user) external view returns (bool) {
        return _registered[_user];
    }
}

contracts/interfaces/ICompliance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ICompliance
 * @dev Interface for compliance engine - handles transfer restrictions and validation
 * @notice This interface defines compliance rules for token transfers
 */
interface ICompliance {
    /**
     * @dev Emitted when compliance rules are updated
     */
    event ComplianceRuleAdded(string indexed ruleType, address indexed target);
    
    /**
     * @dev Emitted when a forced transfer occurs
     */
    event ForcedTransfer(address indexed from, address indexed to, uint256 amount);
    
    /**
     * @dev Check if a transfer is compliant
     * @param _from The sender address
     * @param _to The recipient address  
     * @param _amount The transfer amount
     * @return bool True if transfer is allowed
     */
    function canTransfer(address _from, address _to, uint256 _amount) external view returns (bool);
    
    /**
     * @dev Hook called after token transfer to update holder counts
     * @param _from The sender address
     * @param _to The recipient address
     * @param _amount The transfer amount
     */
    function transferred(address _from, address _to, uint256 _amount) external;

    /**
     * @dev Hook called when tokens are created (minted)
     * @param _to The recipient address
     * @param _amount The amount minted
     */
    function created(address _to, uint256 _amount) external;

    /**
     * @dev Hook called when tokens are destroyed (burned)
     * @param _from The address from which tokens are burned
     * @param _amount The amount burned
     */
    function destroyed(address _from, uint256 _amount) external;
    
    /**
     * @dev Add address to blacklist
     * @param _address The address to blacklist
     */
    function addToBlacklist(address _address) external;
    
    /**
     * @dev Remove address from blacklist  
     * @param _address The address to remove from blacklist
     */
    function removeFromBlacklist(address _address) external;
    
    /**
     * @dev Check if address is blacklisted
     * @param _address The address to check
     * @return bool True if blacklisted
     */
    function isBlacklisted(address _address) external view returns (bool);
    
    /**
     * @dev Get total number of token holders
     * @return uint256 Number of holders
     */
    function getTotalHolders() external view returns (uint256);
}

