// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IIdentityRegistry
 * @dev Interface for identity registry - maintains KYC/AML compliance
 * @notice This interface defines the core functions for managing investor identities
 */
interface IIdentityRegistry {
    /**
     * @dev Emitted when a new identity is registered
     */
    event IdentityRegistered(address indexed wallet, address indexed onchainId);
    
    /**
     * @dev Emitted when an identity is verified by admin
     */
    event IdentityVerified(address indexed wallet, address indexed onchainId, uint16 country);
    
    /**
     * @dev Register an identity (public for demo purposes)
     * @param _onchainId The on-chain identity contract address
     */
    function registerIdentity(address _onchainId) external;
    
    /**
     * @dev Admin verifies an identity after KYC process
     * @param _wallet The wallet address to verify
     * @param _onchainId The on-chain identity contract
     * @param _country ISO 3166-1 country code
     */
    function adminVerify(address _wallet, address _onchainId, uint16 _country) external;
    
    /**
     * @dev Check if a wallet is verified
     * @param _wallet The wallet address to check
     * @return bool True if wallet is KYC verified
     */
    function isVerified(address _wallet) external view returns (bool);
    
    /**
     * @dev Get the country of a verified wallet
     * @param _wallet The wallet address
     * @return uint16 The country code
     */
    function getCountry(address _wallet) external view returns (uint16);
}

contracts/LeaseAgreement.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./interfaces/IERC3643.sol";
import "./interfaces/IIdentityRegistry.sol";

/**
 * @title LeaseAgreement
 * @dev Smart contract for managing lease agreements with tokenized properties
 * Handles lease terms, rent tracking, payments, and dispute resolution
 */
contract LeaseAgreement is AccessControl, ReentrancyGuard, Pausable {
    
    // Roles
    bytes32 public constant LEASE_MANAGER_ROLE = keccak256("LEASE_MANAGER_ROLE");
    bytes32 public constant DISPUTE_RESOLVER_ROLE = keccak256("DISPUTE_RESOLVER_ROLE");
    bytes32 public constant COMPLIANCE_ROLE = keccak256("COMPLIANCE_ROLE");
    
    // Lease status enumeration
    enum LeaseStatus {
        DRAFT,          // Lease terms being negotiated
        ACTIVE,         // Lease is active and rent due
        DEFAULTED,      // Tenant in default (missed payments)
        TERMINATED,     // Lease terminated by either party
        EXPIRED,        // Lease term naturally expired
        DISPUTED        // Lease under dispute resolution
    }
    
    // Payment status
    enum PaymentStatus {
        PENDING,        // Payment due but not made
        PAID,           // Payment completed on time
        LATE,           // Payment made after due date
        PARTIAL,        // Partial payment made
        DEFAULTED       // Payment not made within grace period
    }
    
    // Dispute status
    enum DisputeStatus {
        NONE,           // No dispute
        RAISED,         // Dispute raised by party
        UNDER_REVIEW,   // Dispute being reviewed
        RESOLVED,       // Dispute resolved
        ARBITRATED      // Dispute sent to arbitration
    }
    
    // Lease agreement structure
    struct Lease {
        uint256 leaseId;
        address propertyToken;      // ERC-3643 property token contract
        uint256 propertyTokenId;    // Specific token ID if fractional
        address landlord;           // Property owner
        address tenant;             // Lease holder
        
        // Financial terms
        uint256 monthlyRent;        // Monthly rent in wei (or stablecoin)
        uint256 securityDeposit;    // Security deposit amount
        uint256 totalRentPaid;      // Total rent paid to date
        address paymentToken;       // ERC-20 token for payments (USDC, IRL, etc.)
        
        // Time terms
        uint256 startDate;          // Lease start timestamp
        uint256 endDate;            // Lease end timestamp
        uint256 nextPaymentDue;     // Next rent payment due date
        uint32 gracePeriodDays;     // Grace period for late payment
        
        // Lease terms
        string propertyAddress;     // Physical property address
        string leaseTermsHash;      // IPFS hash of detailed lease terms
        bytes32 documentHash;       // Hash of signed documents
        
        // Status tracking
        LeaseStatus status;
        uint256 createdAt;
        uint256 lastModified;
        
        // Dispute handling
        DisputeStatus disputeStatus;
        string disputeDetails;      // IPFS hash of dispute details
        address disputeRaisedBy;
        uint256 disputeRaisedAt;
    }
    
    // Payment record structure
    struct PaymentRecord {
        uint256 paymentId;
        uint256 leaseId;
        uint256 amount;
        uint256 dueDate;
        uint256 paidDate;
        PaymentStatus status;
        address paidBy;
        string paymentReference;    // Off-chain payment reference
    }
    
    // Storage
    mapping(uint256 => Lease) public leases;
    mapping(uint256 => PaymentRecord[]) public leasePayments;
    mapping(address => uint256[]) public landlordLeases;
    mapping(address => uint256[]) public tenantLeases;
    mapping(address => bool) public approvedPaymentTokens;
    
    uint256 private _leaseCounter;
    uint256 private _paymentCounter;
    
    // Contract references
    IIdentityRegistry public identityRegistry;
    address public escrowContract;
    
    // Configuration
    uint256 public defaultGracePeriod = 5 days;
    uint256 public maxLeaseDuration = 10 * 365 days; // 10 years
    uint256 public minLeaseDuration = 30 days;
    
    // Events
    event LeaseCreated(
        uint256 indexed leaseId,
        address indexed landlord,
        address indexed tenant,
        address propertyToken,
        uint256 monthlyRent
    );
    
    event LeaseStatusChanged(
        uint256 indexed leaseId,
        LeaseStatus oldStatus,
        LeaseStatus newStatus
    );
    
    event RentPaymentMade(
        uint256 indexed leaseId,
        uint256 indexed paymentId,
        uint256 amount,
        address paidBy,
        PaymentStatus status
    );
    
    event DisputeRaised(
        uint256 indexed leaseId,
        address indexed raisedBy,
        string disputeDetails
    );
    
    event DisputeResolved(
        uint256 indexed leaseId,
        address indexed resolvedBy,
        string resolution
    );
    
    event LeaseTermsUpdated(
        uint256 indexed leaseId,
        string newTermsHash
    );
    
    constructor(
        address _identityRegistry,
        address _escrowContract
    ) {
        require(_identityRegistry != address(0), "LeaseAgreement: invalid identity registry");
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(LEASE_MANAGER_ROLE, msg.sender);
        _grantRole(DISPUTE_RESOLVER_ROLE, msg.sender);
        _grantRole(COMPLIANCE_ROLE, msg.sender);
        
        identityRegistry = IIdentityRegistry(_identityRegistry);
        escrowContract = _escrowContract;
        
        // Approve common payment tokens
        // Note: These should be set after deployment based on available tokens
        // approvedPaymentTokens[USDC_ADDRESS] = true;
        // approvedPaymentTokens[IRL_TOKEN_ADDRESS] = true;
    }
    
    // Modifiers
    modifier onlyLeaseManager() {
        require(hasRole(LEASE_MANAGER_ROLE, msg.sender), "LeaseAgreement: not a lease manager");
        _;
    }
    
    modifier onlyDisputeResolver() {
        require(hasRole(DISPUTE_RESOLVER_ROLE, msg.sender), "LeaseAgreement: not dispute resolver");
        _;
    }
    
    modifier onlyLeaseParties(uint256 _leaseId) {
        require(
            msg.sender == leases[_leaseId].landlord || 
            msg.sender == leases[_leaseId].tenant,
            "LeaseAgreement: not a lease party"
        );
        _;
    }
    
    modifier validLease(uint256 _leaseId) {
        require(_leaseId > 0 && _leaseId <= _leaseCounter, "LeaseAgreement: invalid lease ID");
        require(leases[_leaseId].landlord != address(0), "LeaseAgreement: lease not found");
        _;
    }
    
    modifier verifiedParties(address _landlord, address _tenant) {
        require(identityRegistry.isVerified(_landlord), "LeaseAgreement: landlord not verified");
        require(identityRegistry.isVerified(_tenant), "LeaseAgreement: tenant not verified");
        _;
    }
    
    // Core Lease Functions
    
    /**
     * @dev Create a new lease agreement
     */
    function createLease(
        address _propertyToken,
        uint256 _propertyTokenId,
        address _landlord,
        address _tenant,
        uint256 _monthlyRent,
        uint256 _securityDeposit,
        address _paymentToken,
        uint256 _startDate,
        uint256 _endDate,
        string calldata _propertyAddress,
        string calldata _leaseTermsHash,
        bytes32 _documentHash
    ) external 
        whenNotPaused 
        verifiedParties(_landlord, _tenant)
        returns (uint256) 
    {
        require(_propertyToken != address(0), "LeaseAgreement: invalid property token");
        require(_landlord != _tenant, "LeaseAgreement: landlord cannot be tenant");
        require(_monthlyRent > 0, "LeaseAgreement: invalid rent amount");
        require(approvedPaymentTokens[_paymentToken], "LeaseAgreement: payment token not approved");
        require(_startDate >= block.timestamp, "LeaseAgreement: start date in past");
        require(_endDate > _startDate, "LeaseAgreement: invalid lease duration");
        require(_endDate - _startDate >= minLeaseDuration, "LeaseAgreement: lease too short");
        require(_endDate - _startDate <= maxLeaseDuration, "LeaseAgreement: lease too long");
        require(bytes(_leaseTermsHash).length > 0, "LeaseAgreement: missing lease terms");
        
        // Verify landlord owns the property token
        IERC3643 propertyTokenContract = IERC3643(_propertyToken);
        require(propertyTokenContract.balanceOf(_landlord) > 0, "LeaseAgreement: landlord doesn't own property");
        
        _leaseCounter++;
        uint256 leaseId = _leaseCounter;
        
        leases[leaseId] = Lease({
            leaseId: leaseId,
            propertyToken: _propertyToken,
            propertyTokenId: _propertyTokenId,
            landlord: _landlord,
            tenant: _tenant,
            monthlyRent: _monthlyRent,
            securityDeposit: _securityDeposit,
            totalRentPaid: 0,
            paymentToken: _paymentToken,
            startDate: _startDate,
            endDate: _endDate,
            nextPaymentDue: _startDate + 30 days, // First payment due 30 days after start
            gracePeriodDays: uint32(defaultGracePeriod / 1 days),
            propertyAddress: _propertyAddress,
            leaseTermsHash: _leaseTermsHash,
            documentHash: _documentHash,
            status: LeaseStatus.DRAFT,
            createdAt: block.timestamp,
            lastModified: block.timestamp,
            disputeStatus: DisputeStatus.NONE,
            disputeDetails: "",
            disputeRaisedBy: address(0),
            disputeRaisedAt: 0
        });
        
        // Add to landlord and tenant tracking
        landlordLeases[_landlord].push(leaseId);
        tenantLeases[_tenant].push(leaseId);
        
        emit LeaseCreated(leaseId, _landlord, _tenant, _propertyToken, _monthlyRent);
        
        return leaseId;
    }
    
    /**
     * @dev Activate a lease (after security deposit paid)
     */
    function activateLease(uint256 _leaseId) 
        external 
        validLease(_leaseId) 
        onlyLeaseParties(_leaseId) 
    {
        Lease storage lease = leases[_leaseId];
        require(lease.status == LeaseStatus.DRAFT, "LeaseAgreement: lease not in draft");
        require(block.timestamp >= lease.startDate, "LeaseAgreement: lease not started");
        require(block.timestamp <= lease.endDate, "LeaseAgreement: lease expired");
        
        // Note: Security deposit handling should be done through EscrowPayment contract
        // This is a simplified version
        
        LeaseStatus oldStatus = lease.status;
        lease.status = LeaseStatus.ACTIVE;
        lease.lastModified = block.timestamp;
        
        emit LeaseStatusChanged(_leaseId, oldStatus, LeaseStatus.ACTIVE);
    }
    
    /**
     * @dev Record rent payment
     */
    function recordRentPayment(
        uint256 _leaseId,
        uint256 _amount,
        string calldata _paymentReference
    ) external validLease(_leaseId) nonReentrant returns (uint256) {
        Lease storage lease = leases[_leaseId];
        require(lease.status == LeaseStatus.ACTIVE, "LeaseAgreement: lease not active");
        require(_amount > 0, "LeaseAgreement: invalid payment amount");
        
        _paymentCounter++;
        uint256 paymentId = _paymentCounter;
        
        PaymentStatus status;
        uint256 currentTime = block.timestamp;
        
        if (currentTime <= lease.nextPaymentDue) {
            status = _amount >= lease.monthlyRent ? PaymentStatus.PAID : PaymentStatus.PARTIAL;
        } else if (currentTime <= lease.nextPaymentDue + (lease.gracePeriodDays * 1 days)) {
            status = _amount >= lease.monthlyRent ? PaymentStatus.LATE : PaymentStatus.PARTIAL;
        } else {
            status = PaymentStatus.DEFAULTED;
        }
        
        PaymentRecord memory payment = PaymentRecord({
            paymentId: paymentId,
            leaseId: _leaseId,
            amount: _amount,
            dueDate: lease.nextPaymentDue,
            paidDate: currentTime,
            status: status,
            paidBy: msg.sender,
            paymentReference: _paymentReference
        });
        
        leasePayments[_leaseId].push(payment);
        lease.totalRentPaid += _amount;
        
        // Update next payment due if full payment made
        if (_amount >= lease.monthlyRent) {
            lease.nextPaymentDue += 30 days;
        }
        
        // Update lease status if in default
        if (lease.status == LeaseStatus.DEFAULTED && status != PaymentStatus.DEFAULTED) {
            LeaseStatus oldStatus = lease.status;
            lease.status = LeaseStatus.ACTIVE;
            emit LeaseStatusChanged(_leaseId, oldStatus, LeaseStatus.ACTIVE);
        }
        
        lease.lastModified = block.timestamp;
        
        emit RentPaymentMade(_leaseId, paymentId, _amount, msg.sender, status);
        
        return paymentId;
    }
    
    /**
     * @dev Terminate lease
     */
    function terminateLease(uint256 _leaseId, string calldata _reason) 
        external 
        validLease(_leaseId) 
        onlyLeaseParties(_leaseId) 
    {
        Lease storage lease = leases[_leaseId];
        require(
            lease.status == LeaseStatus.ACTIVE || lease.status == LeaseStatus.DEFAULTED,
            "LeaseAgreement: cannot terminate lease in current status"
        );
        
        LeaseStatus oldStatus = lease.status;
        lease.status = LeaseStatus.TERMINATED;
        lease.lastModified = block.timestamp;
        
        emit LeaseStatusChanged(_leaseId, oldStatus, LeaseStatus.TERMINATED);
    }
    
    /**
     * @dev Check for expired leases and update status
     */
    function checkLeaseExpiry(uint256 _leaseId) external validLease(_leaseId) {
        Lease storage lease = leases[_leaseId];
        
        if (block.timestamp > lease.endDate && lease.status == LeaseStatus.ACTIVE) {
            LeaseStatus oldStatus = lease.status;
            lease.status = LeaseStatus.EXPIRED;
            lease.lastModified = block.timestamp;
            
            emit LeaseStatusChanged(_leaseId, oldStatus, LeaseStatus.EXPIRED);
        }
        
        // Check for payment defaults
        if (lease.status == LeaseStatus.ACTIVE && 
            block.timestamp > lease.nextPaymentDue + (lease.gracePeriodDays * 1 days)) {
            
            LeaseStatus oldStatus = lease.status;
            lease.status = LeaseStatus.DEFAULTED;
            lease.lastModified = block.timestamp;
            
            emit LeaseStatusChanged(_leaseId, oldStatus, LeaseStatus.DEFAULTED);
        }
    }
    
    // Dispute Resolution Functions
    
    /**
     * @dev Raise a dispute
     */
    function raiseDispute(uint256 _leaseId, string calldata _disputeDetails) 
        external 
        validLease(_leaseId) 
        onlyLeaseParties(_leaseId) 
    {
        Lease storage lease = leases[_leaseId];
        require(lease.disputeStatus == DisputeStatus.NONE, "LeaseAgreement: dispute already exists");
        require(bytes(_disputeDetails).length > 0, "LeaseAgreement: missing dispute details");
        
        lease.disputeStatus = DisputeStatus.RAISED;
        lease.disputeDetails = _disputeDetails;
        lease.disputeRaisedBy = msg.sender;
        lease.disputeRaisedAt = block.timestamp;
        
        LeaseStatus oldStatus = lease.status;
        lease.status = LeaseStatus.DISPUTED;
        lease.lastModified = block.timestamp;
        
        emit DisputeRaised(_leaseId, msg.sender, _disputeDetails);
        emit LeaseStatusChanged(_leaseId, oldStatus, LeaseStatus.DISPUTED);
    }
    
    /**
     * @dev Resolve a dispute
     */
    function resolveDispute(uint256 _leaseId, string calldata _resolution) 
        external 
        validLease(_leaseId) 
        onlyDisputeResolver 
    {
        Lease storage lease = leases[_leaseId];
        require(lease.disputeStatus == DisputeStatus.RAISED || 
                lease.disputeStatus == DisputeStatus.UNDER_REVIEW, 
                "LeaseAgreement: no dispute to resolve");
        
        lease.disputeStatus = DisputeStatus.RESOLVED;
        lease.lastModified = block.timestamp;
        
        // Revert to active status if lease is still valid
        LeaseStatus oldStatus = lease.status;
        if (block.timestamp <= lease.endDate) {
            lease.status = LeaseStatus.ACTIVE;
        } else {
            lease.status = LeaseStatus.EXPIRED;
        }
        
        emit DisputeResolved(_leaseId, msg.sender, _resolution);
        emit LeaseStatusChanged(_leaseId, oldStatus, lease.status);
    }
    
    // View Functions
    
    /**
     * @dev Get lease details
     */
    function getLease(uint256 _leaseId) 
        external 
        view 
        validLease(_leaseId) 
        returns (Lease memory) 
    {
        return leases[_leaseId];
    }
    
    /**
     * @dev Get lease payment history
     */
    function getLeasePayments(uint256 _leaseId) 
        external 
        view 
        validLease(_leaseId) 
        returns (PaymentRecord[] memory) 
    {
        return leasePayments[_leaseId];
    }
    
    /**
     * @dev Get landlord's leases
     */
    function getLandlordLeases(address _landlord) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return landlordLeases[_landlord];
    }
    
    /**
     * @dev Get tenant's leases
     */
    function getTenantLeases(address _tenant) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return tenantLeases[_tenant];
    }
    
    /**
     * @dev Check if rent is overdue
     */
    function isRentOverdue(uint256 _leaseId) 
        external 
        view 
        validLease(_leaseId) 
        returns (bool) 
    {
        Lease memory lease = leases[_leaseId];
        return (lease.status == LeaseStatus.ACTIVE && 
                block.timestamp > lease.nextPaymentDue);
    }
    
    /**
     * @dev Get next payment due amount and date
     */
    function getNextPaymentInfo(uint256 _leaseId) 
        external 
        view 
        validLease(_leaseId) 
        returns (uint256 amount, uint256 dueDate, bool overdue) 
    {
        Lease memory lease = leases[_leaseId];
        return (
            lease.monthlyRent,
            lease.nextPaymentDue,
            block.timestamp > lease.nextPaymentDue
        );
    }
    
    // Administrative Functions
    
    /**
     * @dev Set approved payment token
     */
    function setApprovedPaymentToken(address _token, bool _approved) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        approvedPaymentTokens[_token] = _approved;
    }
    
    /**
     * @dev Update default grace period
     */
    function setDefaultGracePeriod(uint256 _gracePeriod) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        defaultGracePeriod = _gracePeriod;
    }
    
    /**
     * @dev Update lease duration limits
     */
    function setLeaseDurationLimits(uint256 _minDuration, uint256 _maxDuration) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        require(_minDuration < _maxDuration, "LeaseAgreement: invalid duration limits");
        minLeaseDuration = _minDuration;
        maxLeaseDuration = _maxDuration;
    }
    
    /**
     * @dev Update escrow contract address
     */
    function setEscrowContract(address _escrowContract) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        escrowContract = _escrowContract;
    }
    
    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }
    
    /**
     * @dev Unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }
    
    /**
     * @dev Batch check lease expiries (gas-efficient)
     */
    function batchCheckLeaseExpiry(uint256[] calldata _leaseIds) external {
        for (uint256 i = 0; i < _leaseIds.length; i++) {
            if (_leaseIds[i] > 0 && _leaseIds[i] <= _leaseCounter) {
                this.checkLeaseExpiry(_leaseIds[i]);
            }
        }
    }
}

contracts/LeaseManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/IIdentityRegistry.sol";

/**
 * @title LeaseManager
 * @dev Manages lease agreements and payments for tokenized real estate
 * @notice Purpose: Handle lease creation, security deposits, and rent payments
 * 
 * Expected edits for production:
 * - Add more sophisticated lease terms (variable rent, escalations)
 * - Implement automated dispute resolution mechanisms  
 * - Add integration with off-chain property management systems
 * - Add support for multiple payment tokens per lease
 * 
 * Security notes:
 * - All payments use SafeERC20 for secure token transfers
 * - Reentrancy protection on all state-changing functions
 * - Only verified identities can create or participate in leases
 * - Escrow logic prevents double-spending of deposits
 */
contract LeaseManager is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    
    // Identity registry for KYC verification
    IIdentityRegistry public immutable identityRegistry;
    
    // Lease status enumeration
    enum LeaseStatus {
        CREATED,        // Lease created, waiting for deposit
        ACTIVE,         // Deposit paid, lease is active
        COMPLETED,      // Lease term completed
        TERMINATED,     // Lease terminated early
        DEFAULTED       // Tenant in default
    }
    
    // Lease structure
    struct Lease {
        uint256 leaseId;            // Unique lease identifier
        address landlord;           // Property owner
        address tenant;             // Lease holder
        IERC20 paymentToken;        // Token used for payments (e.g., USDC)
        uint256 monthlyRent;        // Monthly rent amount
        uint256 securityDeposit;    // Security deposit amount
        uint256 leaseStart;         // Lease start timestamp
        uint256 leaseEnd;           // Lease end timestamp
        LeaseStatus status;         // Current lease status
        uint256 depositPaid;        // Amount of deposit actually paid
        uint256 lastRentPayment;    // Timestamp of last rent payment
        uint256 totalRentPaid;      // Total rent paid to date
        string propertyMetadata;    // IPFS CID or property description
    }
    
    // Storage
    mapping(uint256 => Lease) public leases;
    mapping(address => uint256[]) public landlordLeases;    // landlord => lease IDs
    mapping(address => uint256[]) public tenantLeases;      // tenant => lease IDs
    mapping(address => bool) public approvedTokens;        // approved payment tokens
    
    uint256 private _nextLeaseId = 1;
    
    // Events
    event LeaseCreated(
        uint256 indexed leaseId,
        address indexed landlord,
        address indexed tenant,
        uint256 monthlyRent,
        uint256 securityDeposit
    );
    
    event DepositPaid(
        uint256 indexed leaseId,
        address indexed tenant,
        uint256 amount
    );
    
    event RentPaid(
        uint256 indexed leaseId,
        address indexed tenant,
        uint256 amount,
        uint256 timestamp
    );
    
    event DepositReturned(
        uint256 indexed leaseId,
        address indexed tenant,
        uint256 amount
    );
    
    event LeaseStatusChanged(
        uint256 indexed leaseId,
        LeaseStatus oldStatus,
        LeaseStatus newStatus
    );
    
    constructor(address _identityRegistry) Ownable(msg.sender) {
        require(_identityRegistry != address(0), "LeaseManager: invalid identity registry");
        identityRegistry = IIdentityRegistry(_identityRegistry);
    }
    
    /**
     * @dev Create a new lease agreement
     * @param _tenant The tenant address
     * @param _paymentToken The ERC20 token for payments
     * @param _monthlyRent Monthly rent amount
     * @param _securityDeposit Security deposit amount
     * @param _leaseStart Lease start timestamp
     * @param _leaseEnd Lease end timestamp
     * @param _propertyMetadata Property description or IPFS CID
     * @return uint256 The created lease ID
     * @notice Both landlord and tenant must be KYC verified
     */
    function createLease(
        address _tenant,
        IERC20 _paymentToken,
        uint256 _monthlyRent,
        uint256 _securityDeposit,
        uint256 _leaseStart,
        uint256 _leaseEnd,
        string memory _propertyMetadata
    ) external nonReentrant returns (uint256) {
        require(_tenant != address(0), "LeaseManager: invalid tenant");
        require(_tenant != msg.sender, "LeaseManager: landlord cannot be tenant");
        require(address(_paymentToken) != address(0), "LeaseManager: invalid payment token");
        require(approvedTokens[address(_paymentToken)], "LeaseManager: token not approved");
        require(_monthlyRent > 0, "LeaseManager: rent must be positive");
        require(_securityDeposit > 0, "LeaseManager: deposit must be positive");
        require(_leaseStart >= block.timestamp, "LeaseManager: start date in past");
        require(_leaseEnd > _leaseStart, "LeaseManager: invalid lease period");
        require(bytes(_propertyMetadata).length > 0, "LeaseManager: empty property metadata");
        
        // Verify both parties are KYC compliant
        require(identityRegistry.isVerified(msg.sender), "LeaseManager: landlord not verified");
        require(identityRegistry.isVerified(_tenant), "LeaseManager: tenant not verified");
        
        uint256 leaseId = _nextLeaseId++;
        
        // Create lease
        leases[leaseId] = Lease({
            leaseId: leaseId,
            landlord: msg.sender,
            tenant: _tenant,
            paymentToken: _paymentToken,
            monthlyRent: _monthlyRent,
            securityDeposit: _securityDeposit,
            leaseStart: _leaseStart,
            leaseEnd: _leaseEnd,
            status: LeaseStatus.CREATED,
            depositPaid: 0,
            lastRentPayment: 0,
            totalRentPaid: 0,
            propertyMetadata: _propertyMetadata
        });
        
        // Track leases for both parties
        landlordLeases[msg.sender].push(leaseId);
        tenantLeases[_tenant].push(leaseId);
        
        emit LeaseCreated(leaseId, msg.sender, _tenant, _monthlyRent, _securityDeposit);
        
        return leaseId;
    }
    
    /**
     * @dev Pay security deposit for a lease
     * @param _leaseId The lease ID
     * @notice Tenant must approve tokens before calling this function
     */
    function paySecurityDeposit(uint256 _leaseId) external nonReentrant {
        Lease storage lease = leases[_leaseId];
        require(lease.landlord != address(0), "LeaseManager: lease not found");
        require(msg.sender == lease.tenant, "LeaseManager: only tenant can pay deposit");
        require(lease.status == LeaseStatus.CREATED, "LeaseManager: invalid lease status");
        require(lease.depositPaid == 0, "LeaseManager: deposit already paid");
        
        // Transfer security deposit to this contract (escrow)
        lease.paymentToken.safeTransferFrom(
            msg.sender, 
            address(this), 
            lease.securityDeposit
        );
        
        // Update lease state
        lease.depositPaid = lease.securityDeposit;
        lease.status = LeaseStatus.ACTIVE;
        
        emit DepositPaid(_leaseId, msg.sender, lease.securityDeposit);
        emit LeaseStatusChanged(_leaseId, LeaseStatus.CREATED, LeaseStatus.ACTIVE);
    }
    
    /**
     * @dev Pay monthly rent
     * @param _leaseId The lease ID
     * @notice Tenant must approve tokens before calling this function
     */
    function payRent(uint256 _leaseId) external nonReentrant {
        Lease storage lease = leases[_leaseId];
        require(lease.landlord != address(0), "LeaseManager: lease not found");
        require(msg.sender == lease.tenant, "LeaseManager: only tenant can pay rent");
        require(lease.status == LeaseStatus.ACTIVE, "LeaseManager: lease not active");
        require(block.timestamp >= lease.leaseStart, "LeaseManager: lease not started");
        require(block.timestamp <= lease.leaseEnd, "LeaseManager: lease expired");
        
        // Transfer rent directly to landlord
        lease.paymentToken.safeTransferFrom(
            msg.sender,
            lease.landlord,
            lease.monthlyRent
        );
        
        // Update lease state
        lease.lastRentPayment = block.timestamp;
        lease.totalRentPaid += lease.monthlyRent;
        
        emit RentPaid(_leaseId, msg.sender, lease.monthlyRent, block.timestamp);
    }
    
    /**
     * @dev Return security deposit to tenant
     * @param _leaseId The lease ID
     * @param _amount Amount to return (allows partial returns for damages)
     * @notice Only landlord can initiate deposit return
     */
    function returnDeposit(uint256 _leaseId, uint256 _amount) external nonReentrant {
        Lease storage lease = leases[_leaseId];
        require(lease.landlord != address(0), "LeaseManager: lease not found");
        require(msg.sender == lease.landlord, "LeaseManager: only landlord can return deposit");
        require(lease.depositPaid > 0, "LeaseManager: no deposit to return");
        require(_amount <= lease.depositPaid, "LeaseManager: amount exceeds deposit");
        require(
            lease.status == LeaseStatus.ACTIVE || 
            lease.status == LeaseStatus.COMPLETED ||
            lease.status == LeaseStatus.TERMINATED,
            "LeaseManager: invalid status for deposit return"
        );
        
        // Transfer deposit back to tenant
        lease.paymentToken.safeTransfer(lease.tenant, _amount);
        
        // Update deposit tracking
        lease.depositPaid -= _amount;
        
        // If lease is active and we're past end date, mark as completed
        if (lease.status == LeaseStatus.ACTIVE && block.timestamp > lease.leaseEnd) {
            lease.status = LeaseStatus.COMPLETED;
            emit LeaseStatusChanged(_leaseId, LeaseStatus.ACTIVE, LeaseStatus.COMPLETED);
        }
        
        emit DepositReturned(_leaseId, lease.tenant, _amount);
    }
    
    /**
     * @dev Terminate lease early
     * @param _leaseId The lease ID
     * @notice Can be called by either landlord or tenant
     */
    function terminateLease(uint256 _leaseId) external {
        Lease storage lease = leases[_leaseId];
        require(lease.landlord != address(0), "LeaseManager: lease not found");
        require(
            msg.sender == lease.landlord || msg.sender == lease.tenant,
            "LeaseManager: only lease parties can terminate"
        );
        require(lease.status == LeaseStatus.ACTIVE, "LeaseManager: lease not active");
        
        LeaseStatus oldStatus = lease.status;
        lease.status = LeaseStatus.TERMINATED;
        
        emit LeaseStatusChanged(_leaseId, oldStatus, LeaseStatus.TERMINATED);
    }
    
    /**
     * @dev Mark lease as defaulted (non-payment)
     * @param _leaseId The lease ID
     * @notice Only landlord can mark as defaulted
     */
    function markDefault(uint256 _leaseId) external {
        Lease storage lease = leases[_leaseId];
        require(lease.landlord != address(0), "LeaseManager: lease not found");
        require(msg.sender == lease.landlord, "LeaseManager: only landlord can mark default");
        require(lease.status == LeaseStatus.ACTIVE, "LeaseManager: lease not active");
        
        LeaseStatus oldStatus = lease.status;
        lease.status = LeaseStatus.DEFAULTED;
        
        emit LeaseStatusChanged(_leaseId, oldStatus, LeaseStatus.DEFAULTED);
    }
    
    /**
     * @dev Add approved payment token
     * @param _token The token address to approve
     * @notice Only owner can approve new payment tokens
     */
    function addApprovedToken(address _token) external onlyOwner {
        require(_token != address(0), "LeaseManager: invalid token");
        approvedTokens[_token] = true;
    }
    
    /**
     * @dev Remove approved payment token
     * @param _token The token address to remove
     */
    function removeApprovedToken(address _token) external onlyOwner {
        approvedTokens[_token] = false;
    }
    
    /**
     * @dev Get lease details
     * @param _leaseId The lease ID
     * @return Lease struct with all lease information
     */
    function getLease(uint256 _leaseId) external view returns (Lease memory) {
        require(leases[_leaseId].landlord != address(0), "LeaseManager: lease not found");
        return leases[_leaseId];
    }
    
    /**
     * @dev Get landlord's lease IDs
     * @param _landlord The landlord address
     * @return uint256[] Array of lease IDs
     */
    function getLandlordLeases(address _landlord) external view returns (uint256[] memory) {
        return landlordLeases[_landlord];
    }
    
    /**
     * @dev Get tenant's lease IDs
     * @param _tenant The tenant address
     * @return uint256[] Array of lease IDs
     */
    function getTenantLeases(address _tenant) external view returns (uint256[] memory) {
        return tenantLeases[_tenant];
    }
    
    /**
     * @dev Check if rent is overdue
     * @param _leaseId The lease ID
     * @return bool True if rent payment is overdue (>30 days since last payment)
     */
    function isRentOverdue(uint256 _leaseId) external view returns (bool) {
        Lease memory lease = leases[_leaseId];
        require(lease.landlord != address(0), "LeaseManager: lease not found");
        
        if (lease.status != LeaseStatus.ACTIVE) return false;
        if (block.timestamp < lease.leaseStart) return false;
        
        // If no rent has been paid and we're >30 days into lease
        if (lease.lastRentPayment == 0) {
            return (block.timestamp > lease.leaseStart + 30 days);
        }
        
        // If last payment was >30 days ago
        return (block.timestamp > lease.lastRentPayment + 30 days);
    }
    
    /**
     * @dev Get total number of leases created
     * @return uint256 Total lease count
     */
    function getTotalLeases() external view returns (uint256) {
        return _nextLeaseId - 1;
    }
    
    /**
     * @dev Emergency withdrawal (only owner, for stuck funds)
     * @param _token Token to withdraw
     * @param _amount Amount to withdraw
     * @notice Should only be used in emergency situations
     */
    function emergencyWithdraw(IERC20 _token, uint256 _amount) external onlyOwner {
        _token.safeTransfer(owner(), _amount);
    }
    
    // TODO: Add automated rent collection with subscription model
    // TODO: Add integration with property inspection services
    // TODO: Add support for rent escalation clauses
    // TODO: Add integration with legal dispute resolution platforms
    // TODO: Add support for partial payments and payment plans
}

