// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title MockUSDC
 * @dev Mock USDC token for testing lease payments and property transactions
 * @notice Purpose: Provide a testnet ERC20 token that mimics USDC behavior
 * 
 * Expected edits for production:
 * - Replace with actual USDC contract address
 * - Remove minting functions (USDC is centrally controlled)
 * - Add proper upgradeability if needed for mainnet deployment
 * 
 * Features for testing:
 * - Standard ERC20 functionality
 * - Public minting for easy testing
 * - 6 decimal places to match real USDC
 * - Faucet functionality for demo purposes
 */
contract MockUSDC is ERC20, Ownable {
    
    // USDC has 6 decimal places
    uint8 private constant DECIMALS = 6;
    
    // Maximum tokens per faucet request (1000 USDC)
    uint256 public constant FAUCET_AMOUNT = 1000 * 10**DECIMALS;
    
    // Cooldown between faucet requests (24 hours)
    uint256 public constant FAUCET_COOLDOWN = 24 hours;
    
    // Track last faucet usage per address
    mapping(address => uint256) public lastFaucetUsage;
    
    event FaucetUsed(address indexed user, uint256 amount);
    event TokensMinted(address indexed to, uint256 amount);
    
    constructor() ERC20("Mock USD Coin", "MockUSDC") Ownable(msg.sender) {
        // Mint initial supply to deployer for setup (1M USDC)
        _mint(msg.sender, 1_000_000 * 10**DECIMALS);
    }
    
    /**
     * @dev Override decimals to match USDC (6 decimals)
     * @return uint8 Number of decimals (6)
     */
    function decimals() public pure override returns (uint8) {
        return DECIMALS;
    }
    
    /**
     * @dev Public faucet for testing - gives users free tokens
     * @notice Can be called once per day per address
     */
    function faucet() external {
        require(
            block.timestamp >= lastFaucetUsage[msg.sender] + FAUCET_COOLDOWN,
            "MockUSDC: faucet cooldown active"
        );
        
        lastFaucetUsage[msg.sender] = block.timestamp;
        _mint(msg.sender, FAUCET_AMOUNT);
        
        emit FaucetUsed(msg.sender, FAUCET_AMOUNT);
    }
    
    /**
     * @dev Admin mint function for testing scenarios
     * @param to Address to mint tokens to
     * @param amount Amount to mint
     * @notice Only owner can call this function
     */
    function mint(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "MockUSDC: mint to zero address");
        require(amount > 0, "MockUSDC: mint amount must be positive");
        
        _mint(to, amount);
        
        emit TokensMinted(to, amount);
    }
    
    /**
     * @dev Batch mint for multiple addresses (useful for demo setup)
     * @param recipients Array of recipient addresses
     * @param amounts Array of amounts to mint to each recipient
     * @notice Arrays must be same length, only owner can call
     */
    function batchMint(address[] calldata recipients, uint256[] calldata amounts) external onlyOwner {
        require(recipients.length == amounts.length, "MockUSDC: arrays length mismatch");
        require(recipients.length > 0, "MockUSDC: empty arrays");
        
        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "MockUSDC: mint to zero address");
            require(amounts[i] > 0, "MockUSDC: mint amount must be positive");
            
            _mint(recipients[i], amounts[i]);
            emit TokensMinted(recipients[i], amounts[i]);
        }
    }
    
    /**
     * @dev Burn tokens from caller's account
     * @param amount Amount to burn
     */
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }
    
    /**
     * @dev Burn tokens from specified account (requires approval)
     * @param from Address to burn tokens from
     * @param amount Amount to burn
     */
    function burnFrom(address from, uint256 amount) external {
        _spendAllowance(from, msg.sender, amount);
        _burn(from, amount);
    }
    
    /**
     * @dev Get faucet cooldown remaining for an address
     * @param user Address to check
     * @return uint256 Seconds until faucet can be used again (0 if ready)
     */
    function getFaucetCooldownRemaining(address user) external view returns (uint256) {
        uint256 nextUsage = lastFaucetUsage[user] + FAUCET_COOLDOWN;
        if (block.timestamp >= nextUsage) {
            return 0;
        }
        return nextUsage - block.timestamp;
    }
    
    /**
     * @dev Check if address can use faucet
     * @param user Address to check
     * @return bool True if faucet is available for the user
     */
    function canUseFaucet(address user) external view returns (bool) {
        return block.timestamp >= lastFaucetUsage[user] + FAUCET_COOLDOWN;
    }
    
    /**
     * @dev Emergency withdrawal for owner (shouldn't be needed in normal operation)
     * @param to Address to send tokens to
     * @param amount Amount to transfer
     */
    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "MockUSDC: transfer to zero address");
        require(amount <= balanceOf(address(this)), "MockUSDC: insufficient contract balance");
        
        _transfer(address(this), to, amount);
    }
}

contracts/PropertyFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/proxy/Clones.sol";
import "./RealEstateToken.sol";
import "./interfaces/IIdentityRegistry.sol";
import "./interfaces/ICompliance.sol";

/**
 * @title PropertyFactory
 * @dev Factory contract for creating and managing multiple tokenized properties dynamically
 * @notice Purpose: Enable dynamic creation of real estate tokens with flexible parameters
 * 
 * Dynamic Features:
 * - Create unlimited properties with unique parameters
 * - Flexible token economics per property
 * - Dynamic metadata updates via IPFS
 * - Configurable compliance per property type
 * - Property lifecycle management
 */
contract PropertyFactory is AccessControl, ReentrancyGuard {
    
    // Role definitions
    bytes32 public constant PROPERTY_CREATOR_ROLE = keccak256("PROPERTY_CREATOR_ROLE");
    bytes32 public constant PROPERTY_MANAGER_ROLE = keccak256("PROPERTY_MANAGER_ROLE");
    bytes32 public constant COMPLIANCE_ADMIN_ROLE = keccak256("COMPLIANCE_ADMIN_ROLE");
    
    // Core contracts
    address public immutable identityRegistry;
    address public immutable complianceTemplate;
    address public immutable tokenImplementation;
    
    // Property categories for different compliance rules
    enum PropertyCategory {
        RESIDENTIAL,
        COMMERCIAL, 
        INDUSTRIAL,
        MIXED_USE,
        LUXURY,
        AFFORDABLE_HOUSING
    }
    
    // Dynamic property configuration
    struct PropertyConfig {
        string name;                    // Token name
        string symbol;                  // Token symbol  
        PropertyCategory category;      // Property type for compliance
        string location;                // Physical address/coordinates
        string description;             // Property description
        uint256 totalValue;            // Total property valuation (USD)
        uint256 totalSupply;           // Max tokens to mint
        uint256 minInvestment;         // Minimum investment amount
        uint256 maxInvestment;         // Maximum investment per investor
        bool fractionalOwnership;      // Allow fractional ownership
        string metadataCID;            // IPFS CID for detailed metadata
        address[] authorizedManagers;  // Property managers
        uint256 creationTime;          // Creation timestamp
        bool isActive;                 // Property status
    }
    
    // Token economics configuration  
    struct TokenEconomics {
        uint256 managementFee;         // Annual fee (basis points)
        uint256 performanceFee;        // Performance fee (basis points) 
        uint256 liquidityBuffer;       // Reserve for buybacks (basis points)
        bool enableDividends;          // Dividend distribution enabled
        bool enableBuyback;            // Token buyback enabled
        bool enableStaking;            // Staking rewards enabled
        uint256 stakingReward;         // Annual staking reward (basis points)
    }
    
    // Storage
    mapping(uint256 => address) public properties;           // propertyId => token contract
    mapping(uint256 => PropertyConfig) public propertyConfigs;
    mapping(uint256 => TokenEconomics) public tokenEconomics;
    mapping(PropertyCategory => address) public categoryCompliance; // Custom compliance per category
    mapping(address => uint256[]) public creatorProperties;   // creator => property IDs
    
    uint256 private _nextPropertyId = 1;
    uint256 public totalProperties;
    
    // Events
    event PropertyCreated(
        uint256 indexed propertyId,
        address indexed tokenContract,
        address indexed creator,
        string name,
        PropertyCategory category
    );
    
    event PropertyUpdated(
        uint256 indexed propertyId,
        string metadataCID,
        bool isActive
    );
    
    event TokenEconomicsUpdated(
        uint256 indexed propertyId,
        uint256 managementFee,
        uint256 performanceFee
    );
    
    event PropertyManagerAdded(
        uint256 indexed propertyId,
        address indexed manager
    );
    
    constructor(
        address _identityRegistry,
        address _complianceTemplate,
        address _tokenImplementation
    ) {
        require(_identityRegistry != address(0), "PropertyFactory: invalid identity registry");
        require(_complianceTemplate != address(0), "PropertyFactory: invalid compliance template");
        require(_tokenImplementation != address(0), "PropertyFactory: invalid token implementation");
        
        identityRegistry = _identityRegistry;
        complianceTemplate = _complianceTemplate;
        tokenImplementation = _tokenImplementation;
        
        // Setup roles
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PROPERTY_CREATOR_ROLE, msg.sender);
        _grantRole(PROPERTY_MANAGER_ROLE, msg.sender);
        _grantRole(COMPLIANCE_ADMIN_ROLE, msg.sender);
    }
    
    /**
     * @dev Create a new tokenized property with dynamic configuration
     * @param config Property configuration struct
     * @param economics Token economics struct
     * @return propertyId The ID of the created property
     */
    function createProperty(
        PropertyConfig memory config,
        TokenEconomics memory economics
    ) external nonReentrant onlyRole(PROPERTY_CREATOR_ROLE) returns (uint256) {
        require(bytes(config.name).length > 0, "PropertyFactory: invalid name");
        require(bytes(config.symbol).length > 0, "PropertyFactory: invalid symbol");
        require(config.totalValue > 0, "PropertyFactory: invalid total value");
        require(config.totalSupply > 0, "PropertyFactory: invalid total supply");
        require(config.minInvestment > 0, "PropertyFactory: invalid min investment");
        require(config.maxInvestment >= config.minInvestment, "PropertyFactory: invalid max investment");
        
        uint256 propertyId = _nextPropertyId++;
        
        // Set configuration
        config.creationTime = block.timestamp;
        config.isActive = true;
        propertyConfigs[propertyId] = config;
        tokenEconomics[propertyId] = economics;
        
        // Get compliance contract for this category
        address compliance = categoryCompliance[config.category];
        if (compliance == address(0)) {
            compliance = complianceTemplate; // Use default compliance
        }
        
        // Create token contract using minimal proxy (Clones)
        address tokenContract = Clones.clone(tokenImplementation);
        
        // Initialize the token
        RealEstateToken.AssetMetadata memory assetData = RealEstateToken.AssetMetadata({
            propertyAddress: config.location,
            assetPassportCID: config.metadataCID,
            totalValue: config.totalValue,
            tokenizedShares: config.totalSupply,
            isActive: true
        });
        
        RealEstateToken(tokenContract).initialize(
            config.name,
            config.symbol,
            identityRegistry,
            compliance,
            assetData,
            msg.sender
        );
        
        // Store references
        properties[propertyId] = tokenContract;
        creatorProperties[msg.sender].push(propertyId);
        totalProperties++;
        
        // Grant management roles to authorized managers
        for (uint i = 0; i < config.authorizedManagers.length; i++) {
            address manager = config.authorizedManagers[i];
            if (manager != address(0)) {
                RealEstateToken(tokenContract).grantRole(
                    RealEstateToken(tokenContract).MINTER_ROLE(),
                    manager
                );
                emit PropertyManagerAdded(propertyId, manager);
            }
        }
        
        emit PropertyCreated(propertyId, tokenContract, msg.sender, config.name, config.category);
        
        return propertyId;
    }
    
    /**
     * @dev Update property metadata dynamically
     * @param propertyId The property ID to update
     * @param newMetadataCID New IPFS CID for metadata
     * @param isActive New active status
     */
    function updateProperty(
        uint256 propertyId,
        string memory newMetadataCID,
        bool isActive
    ) external onlyRole(PROPERTY_MANAGER_ROLE) {
        require(properties[propertyId] != address(0), "PropertyFactory: property not found");
        
        propertyConfigs[propertyId].metadataCID = newMetadataCID;
        propertyConfigs[propertyId].isActive = isActive;
        
        emit PropertyUpdated(propertyId, newMetadataCID, isActive);
    }
    
    /**
     * @dev Update token economics dynamically
     * @param propertyId The property ID to update
     * @param newEconomics New token economics configuration
     */
    function updateTokenEconomics(
        uint256 propertyId,
        TokenEconomics memory newEconomics
    ) external onlyRole(PROPERTY_MANAGER_ROLE) {
        require(properties[propertyId] != address(0), "PropertyFactory: property not found");
        require(newEconomics.managementFee <= 1000, "PropertyFactory: management fee too high"); // Max 10%
        require(newEconomics.performanceFee <= 2000, "PropertyFactory: performance fee too high"); // Max 20%
        
        tokenEconomics[propertyId] = newEconomics;
        
        emit TokenEconomicsUpdated(propertyId, newEconomics.managementFee, newEconomics.performanceFee);
    }
    
    /**
     * @dev Set category-specific compliance contract
     * @param category Property category
     * @param complianceContract Compliance contract address
     */
    function setCategoryCompliance(
        PropertyCategory category,
        address complianceContract
    ) external onlyRole(COMPLIANCE_ADMIN_ROLE) {
        require(complianceContract != address(0), "PropertyFactory: invalid compliance contract");
        categoryCompliance[category] = complianceContract;
    }
    
    /**
     * @dev Add authorized manager to a property
     * @param propertyId The property ID
     * @param manager Manager address to add
     */
    function addPropertyManager(
        uint256 propertyId,
        address manager
    ) external onlyRole(PROPERTY_MANAGER_ROLE) {
        require(properties[propertyId] != address(0), "PropertyFactory: property not found");
        require(manager != address(0), "PropertyFactory: invalid manager");
        
        address tokenContract = properties[propertyId];
        RealEstateToken(tokenContract).grantRole(
            RealEstateToken(tokenContract).MINTER_ROLE(),
            manager
        );
        
        // Add to authorized managers list
        propertyConfigs[propertyId].authorizedManagers.push(manager);
        
        emit PropertyManagerAdded(propertyId, manager);
    }
    
    /**
     * @dev Get property token contract address
     * @param propertyId The property ID
     * @return address Token contract address
     */
    function getPropertyToken(uint256 propertyId) external view returns (address) {
        return properties[propertyId];
    }
    
    /**
     * @dev Get properties created by an address
     * @param creator Creator address
     * @return uint256[] Array of property IDs
     */
    function getCreatorProperties(address creator) external view returns (uint256[] memory) {
        return creatorProperties[creator];
    }
    
    /**
     * @dev Get property configuration
     * @param propertyId The property ID
     * @return PropertyConfig Property configuration struct
     */
    function getPropertyConfig(uint256 propertyId) external view returns (PropertyConfig memory) {
        return propertyConfigs[propertyId];
    }
    
    /**
     * @dev Get token economics configuration
     * @param propertyId The property ID
     * @return TokenEconomics Token economics struct
     */
    function getTokenEconomics(uint256 propertyId) external view returns (TokenEconomics memory) {
        return tokenEconomics[propertyId];
    }
    
    /**
     * @dev Get properties by category
     * @param category Property category
     * @return uint256[] Array of property IDs in the category
     */
    function getPropertiesByCategory(PropertyCategory category) external view returns (uint256[] memory) {
        uint256[] memory result = new uint256[](totalProperties);
        uint256 count = 0;
        
        for (uint256 i = 1; i < _nextPropertyId; i++) {
            if (propertyConfigs[i].category == category && propertyConfigs[i].isActive) {
                result[count] = i;
                count++;
            }
        }
        
        // Resize array to actual count
        uint256[] memory filteredResult = new uint256[](count);
        for (uint256 j = 0; j < count; j++) {
            filteredResult[j] = result[j];
        }
        
        return filteredResult;
    }
    
    /**
     * @dev Emergency pause/unpause a property
     * @param propertyId The property ID
     * @param paused Pause status
     */
    function emergencyPause(uint256 propertyId, bool paused) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(properties[propertyId] != address(0), "PropertyFactory: property not found");
        
        address tokenContract = properties[propertyId];
        if (paused) {
            // Pause functionality could be added to RealEstateToken
            propertyConfigs[propertyId].isActive = false;
        } else {
            propertyConfigs[propertyId].isActive = true;
        }
        
        emit PropertyUpdated(propertyId, propertyConfigs[propertyId].metadataCID, !paused);
    }
    
    /**
     * @dev Get total number of active properties
     * @return uint256 Number of active properties
     */
    function getActivePropertiesCount() external view returns (uint256) {
        uint256 count = 0;
        for (uint256 i = 1; i < _nextPropertyId; i++) {
            if (propertyConfigs[i].isActive) {
                count++;
            }
        }
        return count;
    }
}

contracts/RealEstateToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/IIdentityRegistry.sol";
import "./interfaces/ICompliance.sol";

/**
 * @title RealEstateToken
 * @dev ERC-3643-like permissioned ERC20 token for real estate tokenization
 * @notice Purpose: Tokenize real estate assets with compliance and identity verification
 * 
 * Expected edits for production:
 * - Add more sophisticated metadata storage (IPFS integration)
 * - Implement dividend distribution mechanisms
 * - Add integration with Integra's RWA Asset Passport
 * - Add support for fractional ownership tracking
 * 
 * Security notes:
 * - All transfers must pass compliance checks
 * - Only verified addresses can receive tokens
 * - AGENT_ROLE can force transfers for compliance
 * - Minting requires MINTER_ROLE
 */
contract RealEstateToken is ERC20, AccessControl, ReentrancyGuard {
    
    // Role definitions
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant AGENT_ROLE = keccak256("AGENT_ROLE");
    bytes32 public constant COMPLIANCE_ROLE = keccak256("COMPLIANCE_ROLE");
    
    // Contract references
    IIdentityRegistry public immutable identityRegistry;
    ICompliance public immutable compliance;
    
    // Token metadata for real estate asset
    struct AssetMetadata {
        string propertyAddress;     // Physical property address
        string assetPassportCID;    // IPFS CID for Integra Asset Passport
        uint256 totalValue;         // Total property valuation in USD
        uint256 tokenizedShares;    // Total shares tokenized
        bool isActive;              // Asset status
    }
    
    AssetMetadata public assetMetadata;
    
    // Events for ERC-3643 compatibility
    event ForcedTransfer(
        address indexed controller,
        address indexed from,
        address indexed to,
        uint256 amount
    );
    
    event AssetPassportUpdated(string indexed cid);
    
    constructor(
        string memory _name,
        string memory _symbol,
        address _identityRegistry,
        address _compliance,
        AssetMetadata memory _assetData
    ) ERC20(_name, _symbol) {
        require(_identityRegistry != address(0), "RealEstateToken: invalid identity registry");
        require(_compliance != address(0), "RealEstateToken: invalid compliance");
        require(bytes(_assetData.propertyAddress).length > 0, "RealEstateToken: invalid property address");
        
        // Set up roles
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
        _grantRole(AGENT_ROLE, msg.sender);
        _grantRole(COMPLIANCE_ROLE, msg.sender);
        
        // Set contract references (immutable)
        identityRegistry = IIdentityRegistry(_identityRegistry);
        compliance = ICompliance(_compliance);
        
        // Set asset metadata
        assetMetadata = _assetData;
        
        emit AssetPassportUpdated(_assetData.assetPassportCID);
    }
    
    /**
     * @dev Initialize function for factory pattern (when using Clones)
     * @param _name Token name
     * @param _symbol Token symbol
     * @param _identityRegistry Identity registry address
     * @param _compliance Compliance contract address
     * @param _assetData Asset metadata
     * @param _admin Admin address for roles
     * @notice Only callable once per clone
     */
    function initialize(
        string memory _name,
        string memory _symbol,
        address _identityRegistry,
        address _compliance,
        AssetMetadata memory _assetData,
        address _admin
    ) external {
        // Ensure this is only called once (for clones)
        require(bytes(name()).length == 0, "RealEstateToken: already initialized");
        require(_admin != address(0), "RealEstateToken: invalid admin");
        
        // Initialize ERC20 name and symbol
        // Note: This is a simplified approach. In production, use proper proxy initialization patterns
        
        // Set up roles for the clone
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(MINTER_ROLE, _admin);
        _grantRole(AGENT_ROLE, _admin);
        _grantRole(COMPLIANCE_ROLE, _admin);
        
        // Set asset metadata for the clone
        assetMetadata = _assetData;
        
        emit AssetPassportUpdated(_assetData.assetPassportCID);
    }
    
    /**
     * @dev Override transfer to include compliance checks
     * @param to The recipient address
     * @param amount The amount to transfer
     * @return bool Success status
     * @notice Ensures recipient is verified and transfer is compliant
     */
    function transfer(address to, uint256 amount) 
        public 
        virtual 
        override 
        returns (bool) 
    {
        address owner = _msgSender();
        
        // Check compliance before transfer
        require(compliance.canTransfer(owner, to, amount), "RealEstateToken: transfer not compliant");
        
        // Execute transfer
        _transfer(owner, to, amount);
        return true;
    }
    
    /**
     * @dev Override transferFrom to include compliance checks
     * @param from The sender address
     * @param to The recipient address
     * @param amount The amount to transfer
     * @return bool Success status
     */
    function transferFrom(address from, address to, uint256 amount) 
        public 
        virtual 
        override 
        returns (bool) 
    {
        address spender = _msgSender();
        
        // Check compliance before transfer
        require(compliance.canTransfer(from, to, amount), "RealEstateToken: transfer not compliant");
        
        // Update allowance and execute transfer
        _spendAllowance(from, spender, amount);
        _transfer(from, to, amount);
        return true;
    }
    
    /**
     * @dev Forced transfer by compliance agent (ERC-3643 requirement)
     * @param from The sender address
     * @param to The recipient address
     * @param amount The amount to force transfer
     * @return bool Success status
     * @notice Only AGENT_ROLE can force transfers for compliance/legal reasons
     */
    function forcedTransfer(address from, address to, uint256 amount) 
        external 
        onlyRole(AGENT_ROLE) 
        nonReentrant
        returns (bool) 
    {
        require(from != address(0), "RealEstateToken: transfer from zero address");
        require(to != address(0), "RealEstateToken: transfer to zero address");
        require(balanceOf(from) >= amount, "RealEstateToken: insufficient balance");
        
        // Must have valid recipient identity (even for forced transfers)
        require(identityRegistry.isVerified(to), "RealEstateToken: recipient not verified");
        
        // Execute forced transfer without compliance check
        _transfer(from, to, amount);
        
        emit ForcedTransfer(_msgSender(), from, to, amount);
        return true;
    }
    
    /**
     * @dev Mint new tokens to verified address
     * @param to The recipient address
     * @param amount The amount to mint
     * @notice Only MINTER_ROLE can mint, recipient must be verified
     */
    function mint(address to, uint256 amount) 
        external 
        onlyRole(MINTER_ROLE) 
        nonReentrant 
    {
        require(to != address(0), "RealEstateToken: mint to zero address");
        require(amount > 0, "RealEstateToken: mint amount must be positive");
        
        // Check compliance for minting (from zero address)
        require(compliance.canTransfer(address(0), to, amount), "RealEstateToken: mint not compliant");
        
        _mint(to, amount);
    }
    
    /**
     * @dev Burn tokens from address
     * @param from The address to burn from
     * @param amount The amount to burn
     * @notice Only MINTER_ROLE can burn tokens
     */
    function burn(address from, uint256 amount) 
        external 
        onlyRole(MINTER_ROLE) 
        nonReentrant 
    {
        require(from != address(0), "RealEstateToken: burn from zero address");
        require(balanceOf(from) >= amount, "RealEstateToken: insufficient balance to burn");
        
        _burn(from, amount);
    }
    
    /**
     * @dev Hook called after any token transfer
     * @param from The sender address (zero for minting)
     * @param to The recipient address (zero for burning)
     * @param amount The amount transferred
     * @notice Updates compliance holder counts and handles post-transfer logic
     */
    function _afterTokenTransfer(address from, address to, uint256 amount) 
        internal 
        virtual
    {
        // Update compliance contract holder counts
        compliance.transferred(from, to, amount);
    }
    
    /**
     * @dev Update asset passport CID
     * @param _cid New IPFS CID for asset passport
     * @notice Only admin can update asset passport reference
     */
    function updateAssetPassport(string memory _cid) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        require(bytes(_cid).length > 0, "RealEstateToken: invalid CID");
        
        assetMetadata.assetPassportCID = _cid;
        emit AssetPassportUpdated(_cid);
    }
    
    /**
     * @dev Update asset metadata
     * @param _propertyAddress New property address
     * @param _totalValue New total valuation
     * @param _tokenizedShares New tokenized shares amount
     * @param _isActive Asset active status
     * @notice Only admin can update asset metadata
     */
    function updateAssetMetadata(
        string memory _propertyAddress,
        uint256 _totalValue,
        uint256 _tokenizedShares,
        bool _isActive
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(bytes(_propertyAddress).length > 0, "RealEstateToken: invalid property address");
        
        assetMetadata.propertyAddress = _propertyAddress;
        assetMetadata.totalValue = _totalValue;
        assetMetadata.tokenizedShares = _tokenizedShares;
        assetMetadata.isActive = _isActive;
    }
    
    /**
     * @dev Get asset metadata
     * @return AssetMetadata struct with all asset information
     */
    function getAssetMetadata() 
        external 
        view 
        returns (AssetMetadata memory) 
    {
        return assetMetadata;
    }
    
    /**
     * @dev Check if address can receive tokens
     * @param account The address to check
     * @return bool True if address can receive tokens
     */
    function canReceive(address account) external view returns (bool) {
        if (account == address(0)) return false;
        return compliance.canTransfer(address(0), account, 1);
    }
    
    /**
     * @dev Get token holder count from compliance
     * @return uint256 Number of token holders
     */
    function getHolderCount() external view returns (uint256) {
        return compliance.getTotalHolders();
    }
    
    /**
     * @dev Check if transfer is allowed between addresses
     * @param from Sender address
     * @param to Recipient address
     * @param amount Transfer amount
     * @return bool True if transfer is allowed
     */
    function canTransfer(address from, address to, uint256 amount) 
        external 
        view 
        returns (bool) 
    {
        return compliance.canTransfer(from, to, amount);
    }
    
    /**
     * @dev Returns true if account has been granted role
     * @param role The role to check
     * @param account The account to check
     * @return bool True if account has role
     */
    function hasRole(bytes32 role, address account) 
        public 
        view 
        virtual 
        override 
        returns (bool) 
    {
        return super.hasRole(role, account);
    }
    
    // TODO: Add dividend distribution functionality
    // TODO: Add integration with Integra's Global Orderbook for secondary trading
    // TODO: Add support for partial ownership transfers and fractional management
    // TODO: Add integration with property valuation oracles
    // TODO: Add emergency pause functionality for compliance requirements
}

